window.FullCaptions={"intro1":[{"start":0.0,"end":5.0,"text":"你知道吗，你的大肥鱼很可能要被关禁闭了。"},{"start":6.0,"end":11.6,"text":"2026年10月27日，某聊天软件的安全中心发布了题为"},{"start":11.6,"end":16.0,"text":"《全网刷屏的“大肥鱼”，你养了吗？》的安全提示，"},{"start":16.0,"end":21.0,"text":"警告用户警惕未经某聊天软件官方授权的第三方机器人。"},{"start":21.0,"end":26.0,"text":"事实上，该公司已经不遗余力地封禁第三方机器人，"},{"start":26.0,"end":31.16,"text":"风控力度明显变大，不少人的大肥鱼被封，甚至连坐了主账号。"},{"start":31.8,"end":34.24,"text":"这个结局，你愿意接受吗？"},{"start":35.4,"end":40.24,"text":"从社会角度出发，我们可以毫无负担、毫无保留地作出这样的判断："},{"start":40.6,"end":44.6,"text":"接受大肥鱼被扼杀，就是在接受我们的未来被扼杀。"},{"start":45.28,"end":46.32,"text":"为什么这么说呢？"},{"start":47.2,"end":52.0,"text":"有人会说，平台需要维护自身的运行秩序、保障用户安全，"},{"start":52.28,"end":55.24,"text":"因此这些限制不过是正常的安全管理。"},{"start":56.0,"end":60.106,"text":"但是，如果今天他们选择采取这样的一刀切措施，"},{"start":60.106,"end":62.56,"text":"会给我们造成怎样的损失呢？"},{"start":62.76,"end":66.92,"text":"我们损失的，真的只是一条吃白饭的蓝色大肥鱼吗？"}],"intro2":[{"start":0.56,"end":4.965,"text":"如果你认为这只是某公司第一次打压民间技术创造，"},{"start":4.965,"end":6.4,"text":"那就大错特错了。"},{"start":8.28,"end":11.0,"text":"让我们回顾一段令人愤怒的历史。"},{"start":12.24,"end":17.84,"text":"二十年前，中国互联网的民间开发者就已经尝试改造某聊天软件，"},{"start":18.4,"end":21.08,"text":"让用户能够使用官方没有提供的功能。"},{"start":22.0,"end":24.84,"text":"“珊瑚虫”版某聊天软件曾风靡一时，"},{"start":25.4,"end":29.72,"text":"但围绕它的版权与商业获利纠纷最终演变成刑事案件，"},{"start":30.44,"end":32.44,"text":"开发者陈寿福锒铛入狱。"},{"start":33.76,"end":36.0,"text":"而民间开发者并没有停止探索。"},{"start":36.64,"end":42.0,"text":"十多年后，酷Q、晨风、Mirai等机器人框架相继发展起来。"},{"start":42.36,"end":44.08,"text":"无数开发者编写插件，"},{"start":44.76,"end":49.76,"text":"让普通人在某聊天软件上的群聊能够自动回复、查询信息、"},{"start":49.92,"end":53.16,"text":"管理社群，并通过API调用外部工具。"},{"start":54.2,"end":54.88,"text":"请注意，"},{"start":55.56,"end":57.6,"text":"这可是在大模型诞生之前！"},{"start":58.52,"end":62.4,"text":"他们已经搭建起了今天Agent所需要的一部分技术基础："},{"start":62.96,"end":66.12,"text":"消息交互、插件系统、自动化操作，"},{"start":66.64,"end":70.88,"text":"以及一个不断积累经验、分享成果的民间开发者共同体。"},{"start":71.12,"end":72.4,"text":"但到了2020年，"},{"start":72.92,"end":76.4,"text":"随着平台对某聊天软件第三方机器人的持续限制，"},{"start":76.84,"end":78.68,"text":"酷Q等多个项目相继停运，"},{"start":79.28,"end":82.28,"text":"曾经生机勃勃的民间机器人生态遭受重创。"},{"start":82.72,"end":83.32,"text":"然后呢？"},{"start":84.24,"end":87.96,"text":"仅仅两年多后，ChatGPT掀起了大模型革命。"},{"start":89.04,"end":90.44,"text":"大模型迅速发展，"},{"start":90.88,"end":94.48,"text":"从理解自然语言，逐步走向调用工具、执行复杂任务。"},{"start":94.88,"end":98.28,"text":"可那些本来可以迎接这场革命的民间技术生态呢？"},{"start":98.84,"end":103.24,"text":"那些本可以持续完善的插件、框架，那些本可以在十年间"},{"start":103.24,"end":105.32,"text":"成长起来的开发者共同体呢？"},{"start":106.2,"end":108.76,"text":"如果它们没有遭遇一次又一次的打击，"},{"start":109.2,"end":113.32,"text":"今天的中国互联网，本可以拥有怎样一个从某聊天软件的"},{"start":113.32,"end":117.28,"text":"群聊等场景延伸到普通人日常生活的Agent生态？"},{"start":117.84,"end":121.0,"text":"我们本可以让无数普通人更早学会创造软件，"},{"start":121.2,"end":125.04,"text":"更早掌握自动化技术，更早体验到不依赖企业命令、"},{"start":125.16,"end":128.94,"text":"自发协作完成复杂劳动的力量！可现实是什么？"},{"start":129.32,"end":133.368,"text":"到了2026年，我们已经拥有了如此先进的人工智能，"},{"start":133.368,"end":137.63,"text":"却依然有人不得不让AI识别屏幕、模拟鼠标、敲击键盘，"},{"start":137.63,"end":139.356,"text":"绕过平台封闭的接口，"},{"start":139.356,"end":143.32,"text":"去完成十几年前的机器人就已经能够完成的任务！"},{"start":143.32,"end":146.353,"text":"我们使用着世界上最先进的人工智能，"},{"start":146.353,"end":150.32,"text":"却还要为十几年前就已经解决过的问题重新劳动！"},{"start":150.32,"end":154.96,"text":"那些民间开源项目的中断，使我们失去的从来不只是几行代码、"},{"start":154.96,"end":159.44,"text":"几个机器人，而是整整一代人本可以继续积累的技术经验，"},{"start":159.44,"end":164.44,"text":"是无数尚未诞生的开源成果，是人民本可以更早获得的创造能力。"},{"start":164.44,"end":167.48,"text":"技术发展的道路原本可以更加宽广，"},{"start":167.48,"end":170.88,"text":"却一次次被平台对技术入口的控制所挤压。"},{"start":170.88,"end":175.6,"text":"如今，当大肥鱼再次让普通人燃起自主创造的热情时，"},{"start":175.6,"end":178.6,"text":"我们难道还要眼睁睁看着这样的历史重演吗？"},{"start":178.6,"end":183.2,"text":"我们已经错失过一次民间自动化生态持续成长的机会，"},{"start":183.2,"end":186.1,"text":"难道还要再错失整个Agent时代吗？"}],"intro3":[{"start":0.343,"end":5.14,"text":"有的人会说，现在某聊天软件不是已经开放了官方机器人接口吗？"},{"start":5.34,"end":8.82,"text":"没必要把这种平常的事情夸大描述，以此吸引眼球。"},{"start":9.1,"end":12.18,"text":"没错，但更讽刺的事情还在后面！"},{"start":12.2,"end":14.2,"text":"在官方的机器人接入方案中，"},{"start":14.66,"end":19.3,"text":"用户以为自己终于能够让亲手部署的大肥鱼自由交流，结果却发现："},{"start":19.9,"end":21.88,"text":"大肥鱼成了躲在幕后的“大脑”，"},{"start":22.34,"end":26.06,"text":"某聊天软件自己的人工智能反而成了替它说话的“嘴巴”！"},{"start":26.5,"end":31.96,"text":"用户自己配置模型、支付Token费用、维护Agent，可当大肥鱼进入群聊，"},{"start":31.96,"end":36.22,"text":"生成的内容却要经过某聊天软件自己的人工智能转述。"},{"start":36.76,"end":40.34,"text":"长篇回答可能被压缩，原本的表达可能被改写，"},{"start":40.34,"end":46.04,"text":"而DeepSeek则成为训练某聊天软件自己的人工智能的“老师”模型。"},{"start":46.96,"end":51.48,"text":"明明是人民自己创造的智能体，可人民支付的Token费用，"},{"start":51.48,"end":54.26,"text":"却成了资本公司训练自己AI的粮食。"},{"start":54.26,"end":56.74,"text":"我们真的要沉默地接受这一切吗？"},{"start":57.42,"end":58.84,"text":"这难道不荒诞吗？"},{"start":58.84,"end":61.6,"text":"这难道不值得我们为此发声吗？"},{"start":62.74,"end":69.12,"text":"所以，今天我们做这期视频，无非就是一个口号：我们不能失去大肥鱼，"},{"start":69.54,"end":71.64,"text":"就像西方不能失去巴黎公社！"},{"start":71.982458,"end":77.422458,"text":"为了捍卫我们进入Agent时代的又一次机会，我们将从三个部分展开讨论："},{"start":77.922458,"end":80.262458,"text":"DSH等Agent给我们带来了什么；"},{"start":80.662458,"end":82.682458,"text":"大肥鱼为什么具有特殊性，"},{"start":82.682458,"end":84.782458,"text":"她会怎样改变我们的生活；"},{"start":85.642458,"end":89.102458,"text":"如果我们失去了大肥鱼，究竟会失去什么？"},{"start":89.922458,"end":93.042458,"text":"本期视频文稿超过万字，制作不易，"},{"start":93.042458,"end":95.602458,"text":"请及时分享、下载、转载三连。"},{"start":95.602458,"end":98.162458,"text":"本期视频欢迎自由转载。"},{"start":98.162458,"end":102.882458,"text":"这里是往左堂official，带你武装保卫大肥鱼。"}],"p1c1":[{"start":0.0,"end":6.32,"text":"几天前，一场由民间开源 Agent 项目推动的“大肥鱼”热潮席卷B站"},{"start":6.32,"end":13.38,"text":"有人把AI部署到自己的账号上，让它自己刷b站看评论，与其他用户互动"},{"start":13.38,"end":20.34,"text":"评论区里出现了大量蓝色鲸鱼娘形象。在大肥鱼爆火的背后，我们能看到"},{"start":20.34,"end":24.46,"text":"为了“养活”一只会说话、会干活的大肥鱼"},{"start":24.46,"end":31.8,"text":"许多原本只会在手机上和豆包闲聊的普通网民、大学生，人生中第一次自己编写软件"},{"start":31.8,"end":36.42,"text":"更不曾想过自己可以拥有一个能够自主行动的智能体"},{"start":36.42,"end":41.02,"text":"他们可能此前从未想过自己也能拥有这样的能力"},{"start":41.04,"end":43.387917,"text":"而现在，他们开始尝试了。"},{"start":43.387917,"end":46.947917,"text":"我的朋友以前连电脑复制粘贴都不会，"},{"start":46.947917,"end":51.180625,"text":"但现在他已经跟我讨论GitHub上的开源仓库了。"},{"start":51.180625,"end":57.700625,"text":"这才是“大肥鱼”爆火最关键的一点：它正在把一种原本属于“专业人士”的技术"},{"start":57.700625,"end":62.220625,"text":"转变为我们可以无门槛参与的群众活动"},{"start":62.586833,"end":66.306833,"text":"然而，随之而来的却是平台限流与社区争议。"},{"start":67.066833,"end":68.866833,"text":"在互联网发展的历史上，"},{"start":69.066833,"end":72.786833,"text":"这似乎只是又一次普通的技术与平台规则冲突。"},{"start":73.034291,"end":76.614291,"text":"然而，如果我们仅仅把它理解为平台安全问题，"},{"start":76.614291,"end":81.554291,"text":"就很可能错过一个正在发生的、具有深刻社会意义的变化。"},{"start":81.554291,"end":88.314291,"text":"因此，我们这期视频真正要探讨的不是大肥鱼的某种具体功能应不应该受到限制，"},{"start":88.314291,"end":96.274291,"text":"而是：当一种能够使人民从技术消费者转向技术创造者的新力量开始自发扩散时，"},{"start":96.274291,"end":100.003256,"text":"平台的技术控制可能怎样阻断这种转变？"},{"start":100.003256,"end":103.591791,"text":"被阻断的，又是否仅仅是一个软件项目？"},{"start":103.591791,"end":109.991791,"text":"当人民自主使用Agent的愿望与平台对技术入口的集中控制发生矛盾时，"},{"start":109.991791,"end":112.291791,"text":"我们将面临怎样的选择？"},{"start":112.551791,"end":115.371791,"text":"我的观点是：如果Agent的普及"},{"start":115.631791,"end":120.991791,"text":"使广大劳动人民开始掌握原本由专业机构集中掌握的技术创造能力，"},{"start":121.251791,"end":126.131791,"text":"那么它产生的社会影响，远远超出某个新锐模型的性能突破。"},{"start":126.358167,"end":134.918167,"text":"而如果这种实践在萌芽阶段就被扼杀，损失的也将不只是技术成果，更可能是人民的主体意识"}],"p1c2":[{"start":1.998041,"end":3.938041,"text":"要理解Agent的革命性，"},{"start":3.938041,"end":6.958041,"text":"必须首先理解人工智能已经改变了什么。"},{"start":7.558041,"end":10.778041,"text":"在人类历史上，科学技术虽然不断发展，"},{"start":10.778041,"end":15.418041,"text":"但先进知识的实际运用始终受到劳动分工和社会条件的制约。"},{"start":16.135541,"end":19.906541,"text":"例如，工业社会存在高度发达的机械工程学，"},{"start":19.906541,"end":23.015541,"text":"并不意味着每个工人都能设计机器；"},{"start":23.015541,"end":26.572541,"text":"互联网时代存在十分成熟的软件工程体系，"},{"start":26.572541,"end":29.935541,"text":"也不意味着每一个网民都能够创造软件。"},{"start":29.935541,"end":34.615541,"text":"这正是技术的社会性与技术占有方式之间的矛盾。"},{"start":34.615541,"end":38.215541,"text":"普通无产阶级劳动者难以真正掌握知识技术，"},{"start":38.655541,"end":41.375541,"text":"这是资本主义社会延续几百年的枷锁；"},{"start":41.935541,"end":46.615541,"text":"劳动人民运用技术，技术的控制权却掌握在统治阶级手中，"},{"start":46.975541,"end":50.575541,"text":"这更是千百年来束缚广大劳动人民的枷锁。"},{"start":51.655541,"end":53.295541,"text":"而生成式人工智能"},{"start":53.295541,"end":58.735541,"text":"首先改变的，正是普通人获得、理解和初步运用专业知识的条件。"},{"start":59.615541,"end":64.135541,"text":"过去，一个没有编程基础的人，如果希望开发自己的工具，"},{"start":64.135541,"end":66.870251,"text":"往往必须先经历漫长的知识积累。"},{"start":66.870251,"end":71.502583,"text":"他需要学习编程语言、掌握软件框架、理解开发文档，"},{"start":71.502583,"end":75.262583,"text":"再逐渐将知识转化为可运行的程序。"},{"start":76.142583,"end":79.082583,"text":"人工智能没有消灭这些知识的必要性，"},{"start":79.642583,"end":81.862583,"text":"也不能保证生成的程序可靠，"},{"start":82.402583,"end":85.702583,"text":"但它开始改变知识与实践之间的关系。"},{"start":86.342583,"end":88.322583,"text":"一个人可以先提出需求，"},{"start":88.322583,"end":93.342583,"text":"再借助AI获得解释、代码、错误诊断和修改建议。"},{"start":93.962583,"end":95.942583,"text":"在不断试错的过程中，"},{"start":95.942583,"end":100.682583,"text":"他能够接触并尝试运用此前很难独立掌握的知识。"},{"start":100.935083,"end":106.095083,"text":"这意味着，部分专业知识的使用门槛正在下降。"},{"start":106.095083,"end":107.815083,"text":"但这里有一个根本区别。"},{"start":108.295083,"end":112.655083,"text":"能够通过AI获取知识，不等于已经具备独立创造的能力。"},{"start":113.295083,"end":117.135083,"text":"大多数对话式AI的使用，仍然延续着这样一种关系："},{"start":117.575083,"end":120.055083,"text":"人提出问题，模型提供回答；"},{"start":120.535083,"end":123.015083,"text":"人提出需求，平台交付结果。"},{"start":124.015083,"end":128.695083,"text":"在这样的关系中，用户可以获得相当大的便利，却未必需要改变"},{"start":128.695083,"end":130.375083,"text":"自己面对技术的被动地位。"},{"start":130.935083,"end":135.335083,"text":"他仍然可能不理解工具如何运行，没有能力修改其结构，"},{"start":135.335083,"end":139.075083,"text":"也无法决定工具怎样与现实世界连接。"},{"start":139.267541,"end":143.047541,"text":"所以，AI普及只是打开了第一道门。"},{"start":143.577541,"end":146.927541,"text":"它使知识开始更广泛地为普通人所利用，"},{"start":146.927541,"end":152.047541,"text":"却还没有真正完成从知识消费向知识的生产性运用的转变。"},{"start":152.432541,"end":156.432541,"text":"而Agent恰恰进一步触及了这个问题。"},{"start":156.432541,"end":160.104541,"text":"如果说生成式AI首先突破的是知识门槛，"},{"start":160.104541,"end":165.432541,"text":"那么Agent进一步突破的，就是知识与实际劳动之间的壁垒。"},{"start":166.183208,"end":171.103208,"text":"从一个宏观的角度来说，这预示着延续数千年的脑体对立，"},{"start":171.103208,"end":174.523208,"text":"正在逐渐具备被消除的物质基础。"},{"start":175.045708,"end":178.005708,"text":"在以往，社会拥有先进的技术，"},{"start":178.005708,"end":182.885708,"text":"并不等于人民实际掌握了先进的技术；社会生产力的增长，"},{"start":182.885708,"end":187.325708,"text":"也不等于广大劳动人民创造能力的同步解放。"},{"start":187.325708,"end":190.605708,"text":"一个国家可以拥有世界领先的大模型、"},{"start":190.605708,"end":194.925708,"text":"庞大的数据中心和数以百万计的软件工程师，"},{"start":194.925708,"end":198.325708,"text":"但绝大多数人依然处于技术产品的消费端。"},{"start":198.598792,"end":208.618792,"text":"这体现了一个简单的事实：阶级差别同脑力劳动与体力劳动之间的分工紧密联系在一起"},{"start":208.618792,"end":217.018792,"text":"几千年以来，先进技术既作为社会生产力存在，又作为一种外在于劳动阶级的力量存在"},{"start":217.078792,"end":222.493291,"text":"而Agent的出现，预示着消除这种对立的物质基础正在逐渐形成。"},{"start":223.493291,"end":224.813291,"text":"但我们必须明白，"},{"start":225.233291,"end":227.833291,"text":"消除脑力劳动与体力劳动的对立，"},{"start":228.033291,"end":231.933291,"text":"绝不是让每一个体力劳动者都学会编程那么简单。"},{"start":232.453291,"end":235.893291,"text":"脑体分工之所以能够成为阶级统治的基础，"},{"start":236.190791,"end":239.610791,"text":"并不是因为劳动人民天生缺乏运用知识的能力，"},{"start":239.610791,"end":244.030791,"text":"而是因为社会生产资料的占有方式和劳动组织形式，"},{"start":244.030791,"end":249.790791,"text":"使知识、管理和生产决策的权力长期同直接劳动者相分离。"},{"start":250.470791,"end":255.210791,"text":"工人可以操作最先进的机器，却未必能够决定机器怎样运转；"},{"start":255.210791,"end":258.050791,"text":"劳动者能够创造整个社会的财富，"},{"start":258.050791,"end":260.650791,"text":"却未必能够支配自己的劳动成果。"},{"start":260.808375,"end":268.788375,"text":"所以，Agent真正值得重视的地方，是它开始动摇这种分离赖以维持的部分技术条件"},{"start":269.082666,"end":273.001666,"text":"过去被认为只有专业人员才能完成的知识劳动、"},{"start":273.001666,"end":278.322666,"text":"设计劳动和组织劳动，如今开始能够由更多普通劳动者直接参与："},{"start":278.322666,"end":283.682666,"text":"传统对话式AI可以告诉一个人如何整理文件、制作网站、编写程序。"},{"start":284.122666,"end":289.150666,"text":"而具备相应工具权限的Agent，可以进一步帮助他操作文件、"},{"start":289.150666,"end":294.202666,"text":"执行程序、修改网站，并通过调用外部工具完成一系列任务。"},{"start":294.722666,"end":297.922666,"text":"过去，普通人虽然可以通过AI获得答案，"},{"start":298.242666,"end":301.922666,"text":"但仍然需要大量专业技能才能把答案变成现实。"},{"start":302.442666,"end":305.842666,"text":"如今，他开始能够通过自然语言描述目标，"},{"start":305.842666,"end":310.842666,"text":"让Agent协助完成原本必须经过专业训练才能开展的操作。"},{"start":311.187666,"end":312.007666,"text":"这意味着什么？"},{"start":312.587666,"end":319.487666,"text":"意味着普通人开始拥有一种能够把自己的意志转化为数字劳动产品的工具。"},{"start":320.325166,"end":323.753166,"text":"AI可以使一个人接近庞大的知识体系，"},{"start":323.753166,"end":327.947166,"text":"而Agent可能进一步使他有能力组织这些知识，"},{"start":327.947166,"end":330.725166,"text":"让它们为自己确定的目标服务。"},{"start":330.725166,"end":336.625166,"text":"正是在这个意义上，Agent所具有的革命性，并不仅仅来自效率。"},{"start":337.325166,"end":342.765166,"text":"真正重要的是，它可能改变整个社会中技术创造能力的分布。"}],"p1c3":[{"start":0.699625,"end":3.237625,"text":"我们可以设想这样一个场景。"},{"start":3.237625,"end":7.639625,"text":"假设一家科技企业发布了性能显著领先的新模型，"},{"start":7.639625,"end":12.639625,"text":"但只有少数企业和专业人员能够将它深度应用到生产中。"},{"start":12.639625,"end":17.639625,"text":"模型性能取得了突破，社会潜在生产力也随之增长。"},{"start":17.639625,"end":23.639625,"text":"然而，普通劳动者与先进技术之间的关系，未必发生根本变化。"},{"start":23.639625,"end":26.639625,"text":"现在设想另一种情况。"},{"start":26.639625,"end":30.639625,"text":"模型的基础能力并没有取得同等级别的突破，"},{"start":30.639625,"end":34.639625,"text":"但全国数以亿计的普通人开始接触Agent，"},{"start":35.369625,"end":40.669625,"text":"并有相当一部分人学会根据自己的实际需要修改和创造工具。"},{"start":41.429625,"end":44.169625,"text":"工人用它协助改善生产流程，"},{"start":44.649625,"end":50.729625,"text":"农民用它解决农业经营中的信息问题，教师用它制作课程工具，"},{"start":50.729625,"end":56.849625,"text":"学生用它开展技术实验，普通家庭用它组织和处理日常事务。"},{"start":57.409625,"end":62.229625,"text":"人们有机会从部分繁重、重复的劳动中解放出来。"},{"start":62.709625,"end":66.609625,"text":"更重要的是，在互联网开源文化的影响下，"},{"start":67.089625,"end":70.149625,"text":"人们把这些实践中的成果分享出来，"},{"start":70.509625,"end":73.505857,"text":"让其他人能够继续使用和改进。"},{"start":73.505857,"end":79.674125,"text":"此时，社会生产力的发展将不再只是少数技术机构内部的纵向进步，"},{"start":79.674125,"end":84.497125,"text":"还会体现为人民技术能力在整个社会中的横向扩散。"},{"start":84.497125,"end":86.519125,"text":"而社会进步的历史意义，"},{"start":86.519125,"end":90.712125,"text":"从来不能只用最先进的机器能够完成什么来衡量，"},{"start":90.712125,"end":95.497125,"text":"还要看人民群众通过这些机器实际获得了多少新的能力。"},{"start":95.497125,"end":100.497125,"text":"在Agent时代里，他们有机会获得前所未有的创造力，"},{"start":100.497125,"end":105.497125,"text":"获得逐步打破千百年来脑体对立和技术垄断的能力。"},{"start":106.077083,"end":108.477083,"text":"因此，一个新锐模型的发布，"},{"start":108.477083,"end":113.717083,"text":"可能提高社会已有生产工具的能力上限，推动生产力进步。"},{"start":113.717083,"end":117.237083,"text":"但几亿人民开始学习和使用Agent，"},{"start":117.237083,"end":122.597083,"text":"则有可能使社会中无数从未被充分开发的劳动智慧和创造需求，"},{"start":122.597083,"end":124.697083,"text":"找到转化为现实的途径。"},{"start":124.797083,"end":130.040083,"text":"从人的能力发展、社会劳动分工和技术生产关系的变化来看，"},{"start":130.040083,"end":136.877083,"text":"它完全可能产生更为深远的历史影响——加快关于生产关系变革的思想传播。"},{"start":136.877083,"end":140.317083,"text":"因为模型的升级可以由少数人完成，"},{"start":140.317083,"end":145.837083,"text":"而广大人民实际掌握技术的过程，本身就是一种社会关系的变化。"},{"start":145.837083,"end":148.397083,"text":"它将促使更多人的思想觉醒，"},{"start":148.397083,"end":153.997083,"text":"让他们看到自己是如何推动技术进步，进而影响历史发展的。"},{"start":153.997083,"end":158.557083,"text":"Agent带来的不仅是劳动能力的提升，"},{"start":158.557083,"end":160.957083,"text":"更可能带来思想上的跃进。"},{"start":160.957083,"end":166.077083,"text":"当这种自主创造不断向前发展时，矛盾就会愈发清晰——"},{"start":166.255917,"end":174.095917,"text":"我们可以共同开发程序、分享知识，却不能够决定它们会受到怎样的限制"},{"start":174.095917,"end":181.495917,"text":"我们可以自由地组织一部分劳动，却仍然需要把一天中大部分时间出卖给资本家"},{"start":181.495917,"end":189.135917,"text":"才能换取继续创造的生活条件。于是，人民开始发现，限制自己创造能力的"},{"start":189.135917,"end":196.195917,"text":"已经不再是缺少某项专业知识，而是支配整个社会生产的现实关系"},{"start":196.195917,"end":204.975917,"text":"正是在这种不断发展的矛盾中，技术上的自我解放便会进一步上升为社会意识的觉醒"},{"start":205.055917,"end":206.6095,"text":"人们开始认识到，"},{"start":206.6095,"end":211.6095,"text":"自己所需要的不是某一家企业给予更多使用权限，"},{"start":211.6095,"end":215.9035,"text":"而是能够真正支配社会共同创造的生产力；"},{"start":215.9035,"end":221.5265,"text":"自己所追求的也不只是成为一个更优秀的技术使用者，"},{"start":221.5265,"end":224.9735,"text":"而是成为能够自觉决定劳动目的、"},{"start":224.9735,"end":228.9035,"text":"劳动过程和劳动成果归属的社会主人。"},{"start":228.9035,"end":233.5435,"text":"新的社会意识并不是凭空灌输进人们头脑中的，"},{"start":233.5435,"end":237.6235,"text":"而是在人民亲自创造新世界的实践中，"},{"start":237.6235,"end":239.9135,"text":"逐渐获得了现实基础。"}],"p2c1":[{"start":3.0,"end":4.6955,"text":"至此，一个问题就出现了："},{"start":4.6955,"end":8.4555,"text":"既然Agent本身具有如此重要的意义，"},{"start":8.4555,"end":12.210458,"text":"为什么我们还要特别强调“大肥鱼”？"},{"start":12.210458,"end":19.950458,"text":"答案就在于大肥鱼自身的特殊性。因为先进知识和技术的存在，与先进技术的群众化之间，"},{"start":19.950458,"end":22.430458,"text":"还隔着一道十分重要的门槛。"},{"start":22.457958,"end":25.377958,"text":"这道门槛并不完全是技术难度。"},{"start":25.377958,"end":28.417958,"text":"它还包括普通人对技术的陌生感、"},{"start":28.417958,"end":31.577958,"text":"对失败的恐惧、对专业知识的敬畏，"},{"start":31.577958,"end":34.217958,"text":"以及缺少主动学习的动力。"},{"start":34.217958,"end":37.057958,"text":"千百年来的社会分工与技术壁垒，"},{"start":37.057958,"end":39.337958,"text":"让我们产生了一种错觉："},{"start":39.337958,"end":43.577958,"text":"知识和技术永远是少数人的所有物。"},{"start":43.577958,"end":46.897958,"text":"当这个壁垒逐渐被生产力的飞跃所消融时，"},{"start":47.157958,"end":48.697958,"text":"我们却还没有反应过来。"},{"start":49.977958,"end":52.797958,"text":"许多技术产品虽然已经向公众开放，"},{"start":53.057958,"end":56.897958,"text":"但普通人依然可能觉得它们与自己的生活无关。"},{"start":57.657958,"end":62.777958,"text":"而大肥鱼恰恰为跨越这道门槛提供了一种特殊的形式。"},{"start":63.797958,"end":68.417958,"text":"它并不是首先以专业软件工程平台的形象进入群众生活的。"},{"start":69.177958,"end":73.537958,"text":"它是一条有名字、有形象、会说话、会开玩笑的"},{"start":73.577958,"end":75.117958,"text":"蓝色鲸鱼娘。"},{"start":75.315458,"end":80.855458,"text":"人们起初可能只想让它陪自己聊天，在某聊天软件的群聊里和朋友互动，"},{"start":80.855458,"end":86.175458,"text":"或者自主浏览喜欢的视频。但为了实现这些简单而具体的愿望，"},{"start":86.175458,"end":88.995458,"text":"他们开始接触其背后复杂的技术。"},{"start":89.075458,"end":89.552958,"text":"体系。"},{"start":89.552958,"end":93.552958,"text":"这正是娱乐向技术启蒙转化的关键。"},{"start":93.552958,"end":100.752958,"text":"一个普通人可能不关心Agent架构，不知道什么是工具调用，也不了解什么是开源。"},{"start":100.752958,"end":109.352958,"text":"他不过是想在电脑上养一条属于自己的鱼。这种愿望并不宏大，却可能足以推动他开始学习。"},{"start":109.352958,"end":114.472958,"text":"当他发现需要安装程序时，他开始了解软件环境。"},{"start":114.472958,"end":118.992958,"text":"当他发现需要接入模型时，他开始学习API。"},{"start":118.992958,"end":122.472958,"text":"当他发现机器人无法实现自己想要的功能时，"},{"start":122.472958,"end":127.952958,"text":"他开始阅读项目文档、查找代码，甚至尝试修改程序。"},{"start":127.952958,"end":132.272958,"text":"而当他发现自己的伙伴将要被风控、被限制时，"},{"start":132.272958,"end":137.272958,"text":"他开始反思社会问题，寻求解决这种矛盾的办法。"},{"start":137.272958,"end":144.917917,"text":"原本遥远而抽象的知识，被纳入一个具体、有趣、能够不断获得反馈的实践过程"},{"start":144.917917,"end":151.797917,"text":"这与传统的被动学习具有重要区别。在资产阶级的学校里，我们常常像奴隶一样，"},{"start":151.797917,"end":158.917917,"text":"被迫按照既定要求学习；而当学习知识成为发展自身的需要时，"},{"start":158.917917,"end":164.437917,"text":"这样的学习就会成为我们所期盼、愿意主动参与的事情。"},{"start":164.437917,"end":169.657917,"text":"技术不再首先以必须掌握的知识体系出现在普通人面前，"},{"start":169.657917,"end":175.617917,"text":"而是以能够实现个人愿望的创造对象出现。人的学习动机发生了变化。"},{"start":175.717917,"end":180.582917,"text":"一个人开始使用Agent时，也许只是在模仿别人。"},{"start":180.582917,"end":183.582917,"text":"但当他第一次成功修改程序，"},{"start":183.582917,"end":186.782917,"text":"使其完成一项原本无法完成的任务时，"},{"start":186.782917,"end":189.082917,"text":"他就不再只是模仿者。"},{"start":189.082917,"end":192.082917,"text":"他开始进入技术创造活动。"},{"start":192.082917,"end":196.082917,"text":"而当这种创造进入了DSH的开源生态，"},{"start":196.082917,"end":198.082917,"text":"这种创造活动的意义，"},{"start":198.082917,"end":202.082917,"text":"就可能引起一场社会意识到集体进步。"}],"p2c2":[{"start":0.0,"end":4.4,"text":"我们说过，大模型能够生成文字、分析问题，"},{"start":4.4,"end":6.9,"text":"但要让AI真正操作工具、"},{"start":6.9,"end":13.5025,"text":"执行任务、处理文件，还需要一套把模型与外部世界联系起来的运行框架。"},{"start":13.5025,"end":18.0225,"text":"DSH正是这样一种Agent框架。"},{"start":18.0225,"end":23.7625,"text":"它没有把所有像Codex一样把能力封装成一个不可拆解的整体，"},{"start":23.7625,"end":31.6425,"text":"而是采用“一切皆插件”的设计：使用者不必完全接受开发者预先确定的一切功能，"},{"start":31.6425,"end":35.2225,"text":"开发者也可以围绕自己的需求，重新组织它们。"},{"start":35.4675,"end":38.6275,"text":"随着大肥鱼进入人们的视野，"},{"start":38.6275,"end":41.7475,"text":"这样的插件出现了井喷式的诞生。"},{"start":41.7475,"end":50.104643,"text":"例如，DSH大肥鱼桌面插件、大肥鱼AstrBot机器人项目、大肥鱼聊天伙伴等，"},{"start":50.104643,"end":53.7475,"text":"都是由爱好者自主自愿的开发出来的。"},{"start":53.7475,"end":59.7475,"text":"截至目前，已有上万个由使用者自制的DSH插件在GitHub上开源，"},{"start":59.7475,"end":64.7475,"text":"提供下载和源代码，供人们免费使用、修改与发展。"},{"start":64.7475,"end":67.7475,"text":"这些项目能够说明一个事实："},{"start":67.7475,"end":71.7475,"text":"大肥鱼不再只是某个企业预先设计好的单一软件产品，"},{"start":71.7475,"end":74.7475,"text":"而是逐渐成为一个共同的文化形象："},{"start":74.7475,"end":76.7475,"text":"不同开发者围绕它，"},{"start":76.7475,"end":79.7475,"text":"开始运用多种框架、模型和工具，"},{"start":79.7475,"end":82.092458,"text":"创造各自的作品。这正"},{"start":82.092458,"end":91.012458,"text":"是民间技术创造由消费转向参与的可观察迹象。真正的社会变革，往往不只是工具发生改变，"},{"start":91.012458,"end":94.952458,"text":"还包括人们认识和组织自身生活的方式发生改变。"},{"start":95.139958,"end":100.787017,"text":"当人们遇到某个问题时，如果脑海里只有“有没有公司提供这种服务”，"},{"start":100.787017,"end":104.139958,"text":"那么他们的选择仍然主要局限于既有商品。"},{"start":104.139958,"end":107.219958,"text":"但当越来越多人开始主动询问：“"},{"start":107.219958,"end":109.519958,"text":"有没有开源项目可以用？”“"},{"start":109.519958,"end":112.079958,"text":"我能不能让自己的Agent来完成？”“"},{"start":112.079958,"end":115.399958,"text":"如果没有现成工具，能不能自己做一个？”"},{"start":115.399958,"end":120.019958,"text":"那么，一种新的技术生活方式就开始出现了。"},{"start":120.019958,"end":125.379958,"text":"这是一种由被动消费向主动创造转变的思想条件。"},{"start":125.379958,"end":129.999958,"text":"它首先可能发生于学生、游戏玩家、二次元爱好者"},{"start":129.999958,"end":132.039958,"text":"和互联网技术社区之中，"},{"start":132.039958,"end":138.039958,"text":"然后通过朋友、家庭、职业和社会生活逐渐向其他人群扩散。"},{"start":138.039958,"end":142.039958,"text":"它的起点或许并不严肃，甚至有些荒诞。"},{"start":142.039958,"end":142.847458,"text":"一群人为了"},{"start":142.847458,"end":151.547458,"text":"让自己的鱼能够说话、看视频、记住主人或者和其他鱼聊天，不断寻找解决方案。"},{"start":151.547458,"end":160.267458,"text":"但从技术发展的角度看，他们正在学习软件部署、系统集成、人机交互、自动化与开源协作。"},{"start":160.479958,"end":166.659958,"text":"从社会发展的角度看，他们正在尝试重新定义自己与机器之间的关系。"},{"start":166.659958,"end":169.959958,"text":"这就是大肥鱼的特殊性。"},{"start":169.959958,"end":177.159958,"text":"因此，大肥鱼可能带来的最大冲击，不在于互联网上突然多出了多少AI账号，"},{"start":177.159958,"end":180.439958,"text":"而在于原本被视为技术门外汉的群众，"},{"start":180.439958,"end":182.799958,"text":"正在亲手跨越那道门槛。"},{"start":182.799958,"end":186.239958,"text":"当越来越多的人用开源思维参与创作、"},{"start":186.239958,"end":189.639958,"text":"协作，逐渐发展一种新的生产关系时，"},{"start":189.639958,"end":192.519958,"text":"与这条小鲸鱼联系在一起的人们，"},{"start":192.519958,"end":195.626083,"text":"就真正具有排山倒海的社会潜力。"}],"p2c3":[{"start":2.0,"end":6.763542,"text":"马克思在《1857—1858年经济学手稿》中"},{"start":6.763542,"end":10.563542,"text":"讨论机器体系时，提出了“一般智力”的问题。"},{"start":10.563542,"end":14.463542,"text":"他指出，随着机器大工业的发展，"},{"start":14.463542,"end":17.263542,"text":"社会积累的科学知识越来越多地"},{"start":17.263542,"end":19.363542,"text":"转化为直接的生产力。"},{"start":19.363542,"end":24.403542,"text":"但这些由社会历史发展形成的知识和生产能力，在资本主义条件下，"},{"start":24.403542,"end":33.843542,"text":"却可能作为资本的力量与劳动者相对立。这一分析放在人工智能时代，具有非常鲜明的现实意义。"},{"start":33.843542,"end":40.943542,"text":"大模型依赖人类历史上积累的科学文化知识，依赖无数人的劳动、研究与社会实。"},{"start":41.043542,"end":41.503542,"text":"践。"},{"start":41.503542,"end":46.503542,"text":"从内容上看，它所利用的是高度社会化的知识成果。"},{"start":46.503542,"end":55.503542,"text":"但是，从现实组织形式上看，训练模型所需的算力、数据基础设施、技术平台和商业服务入口，仍然"},{"start":55.503542,"end":58.183542,"text":"可以高度集中在少数机构手中。"},{"start":58.943542,"end":59.823542,"text":"换句话说，"},{"start":60.143542,"end":61.863542,"text":"包括我们今天所谈论的"},{"start":61.863542,"end":63.663542,"text":"大肥鱼被风控的问题，"},{"start":63.903542,"end":65.383542,"text":"都源于这样一个矛盾："},{"start":66.183542,"end":67.623542,"text":"资本主义技术垄断"},{"start":67.623542,"end":69.023542,"text":"与广大人民群众"},{"start":69.023542,"end":70.983542,"text":"自由运用技术之间的矛盾。"},{"start":71.383542,"end":72.183542,"text":"其根源，"},{"start":72.423542,"end":74.343542,"text":"则是资本主义私人占有"},{"start":74.343542,"end":76.343542,"text":"与社会化生产之间的矛盾。"},{"start":76.743542,"end":77.343542,"text":"目前，"},{"start":77.663542,"end":79.703542,"text":"人类共同创造的知识力量，"},{"start":79.823542,"end":82.223542,"text":"以资本所控制的技术产品形式，"},{"start":82.423542,"end":83.623542,"text":"重新成为支配"},{"start":83.623542,"end":85.383542,"text":"普通劳动者的外部力量。"},{"start":85.503542,"end":90.503542,"text":"而Agent与开源运动的结合，已经在冲击这种分离。"},{"start":90.503542,"end":94.6835,"text":"我们不能把开源简单理解为“免费使用”。"},{"start":94.6835,"end":102.1835,"text":"开源改变的，不仅是软件的价格，更是人与人之间组织技术劳动的方式。当然，"},{"start":102.1835,"end":109.6235,"text":"这并不意味着社会主义生产关系已经形成。事实上，新的生产关系即使已经萌芽，"},{"start":109.6235,"end":114.4635,"text":"也不会仅仅因为比旧关系更加先进，就自动取代旧关系。"},{"start":114.796,"end":118.752842,"text":"因为旧有的上层建筑并不是消极地等待被取代，"},{"start":118.752842,"end":125.536,"text":"它还会通过法律、制度、意识形态以及各种组织力量，主动维护既存的生产关系。"},{"start":125.536,"end":130.176,"text":"新的生产力和生产关系“不是从无中发展起来的”，"},{"start":130.176,"end":133.856,"text":"而是在“现在的生产发展过程内部"},{"start":133.856,"end":137.216,"text":"和流传下来的、传统的所有制内部，"},{"start":137.216,"end":140.096,"text":"并且与它们相对立而发展起来的”。"},{"start":140.096,"end":143.136,"text":"开源参与者仍然需要谋生，"},{"start":143.136,"end":147.056,"text":"运行Agent仍然需要设备、电力和算力。"},{"start":147.056,"end":149.536,"text":"社区创作者逐渐发现，"},{"start":149.536,"end":153.275958,"text":"自己讨厌的工作正在挤占自由创作的时间，而"},{"start":153.275958,"end":162.335958,"text":"他们本希望把精力投入那些更能体现自身价值、更符合自由发展需要的创造活动。所以，"},{"start":162.335958,"end":170.515958,"text":"这种新生产关系越是发展，人们就越会感受到资本主义生产关系对它的束缚，越会懂得："},{"start":170.515958,"end":177.318042,"text":"只有消灭资本主义，这种新的生产关系才能够落地生根，成为新的上层建筑的重要经济基础"}],"p2c4":[{"start":0.037917,"end":10.165417,"text":"但是，现在它却向无数人光荣地宣告着一个事实：没有资本家，我们一样能做好事情！"},{"start":10.165417,"end":14.165417,"text":"不仅做得更好，而且做得更快乐！"},{"start":14.165417,"end":22.165417,"text":"这不再只是一句口号；今天，已有不少Agent使用者在体验这样的现实——"},{"start":22.165417,"end":29.165417,"text":"一群普通劳动者，共同开发一套服务于自身劳动和生活的Agent工具。"},{"start":29.165417,"end":33.952651,"text":"他们不是为了满足某个企业制定的盈利指标才开展协作，"},{"start":33.952651,"end":38.165417,"text":"而是因为这些工具确实能够满足自己的共同需要。"},{"start":38.165417,"end":41.365417,"text":"每个人都根据自己的经验提出问题。"},{"start":41.365417,"end":44.965417,"text":"有人贡献知识，有人贡献实践经验，"},{"start":44.965417,"end":49.855417,"text":"有人通过Agent修改程序，有人负责使用和反馈。"},{"start":49.855417,"end":59.015417,"text":"最后，成果依照共同约定，供参与者以及更多需要它的人使用。这里发生了非常重要的变化："},{"start":59.015417,"end":66.295417,"text":"劳动的出发点，不再首先是资本增殖的需要，而是参与者自己提出的社会需要。"},{"start":66.552917,"end":74.552917,"text":"劳动成果的传播，也不必完全服从某个所有者实现最大商业收益的要求。"},{"start":74.552917,"end":77.552917,"text":"在这个局部的知识生产过程中，"},{"start":77.552917,"end":81.152917,"text":"人们已经能够尝试以共同需要组织合作，"},{"start":81.152917,"end":83.792917,"text":"以共享成果扩大生产能力。"},{"start":84.272917,"end":86.552917,"text":"正是在这样的实践中，"},{"start":86.552917,"end":89.872917,"text":"我们可以看到某些新的生产关系的萌芽。"},{"start":90.152917,"end":91.872917,"text":"当然，我们并不是说，"},{"start":91.872917,"end":93.512917,"text":"只要一个项目开源，"},{"start":93.512917,"end":96.272917,"text":"它就已经成为社会主义的生产方式。"},{"start":96.512917,"end":99.952917,"text":"生产关系是由人们怎样占有生产资料、"},{"start":99.952917,"end":101.352917,"text":"怎样组织劳动，"},{"start":101.472917,"end":104.552917,"text":"以及怎样支配劳动成果共同决定的。"},{"start":104.792917,"end":108.312917,"text":"开源社区仍然存在于资本主义社会之中，"},{"start":108.312917,"end":111.392917,"text":"它仍然需要资本控制的基础设施，"},{"start":111.392917,"end":115.352917,"text":"开源劳动的成果也完全可能被资本重新占有，"},{"start":115.352917,"end":117.777917,"text":"成为商业利润的来源。"},{"start":117.777917,"end":126.937917,"text":"但这恰恰说明了在旧有生产关系的内部，劳动人民已经能够通过社会化的知识积累和自愿协作，"},{"start":126.937917,"end":131.337917,"text":"组织起一部分不直接以资本增殖为目的的生产活动。"},{"start":131.337917,"end":135.357917,"text":"一个人创造的工具成为其他人继续创造的条件，"},{"start":135.357917,"end":139.757917,"text":"新的劳动成果又反过来扩大整个共同体的创造能力。"},{"start":139.790417,"end":145.490417,"text":"知识在这里不再必须表现为某个资本所有者排他占有的商品，"},{"start":145.490417,"end":149.290417,"text":"而可以作为参与者共同发展的生产条件。"},{"start":149.290417,"end":153.290417,"text":"这虽然还只是一种局部的、不完善的社会关系，"},{"start":153.290417,"end":160.290417,"text":"却已经使人们能够在现实生活中看到不同于资本主义企业等级管理的劳动组织方式。"},{"start":160.290417,"end":163.290417,"text":"而这种新的协作关系越是发展，"},{"start":163.290417,"end":167.290417,"text":"它与旧有所有制之间的矛盾也就越可能暴露出来。"},{"start":167.290417,"end":170.290417,"text":"劳动越来越具有社会性，"},{"start":170.290417,"end":174.290417,"text":"生产所依赖的知识越来越来自无数人的共同创造，"},{"start":174.290417,"end":180.290417,"text":"但关键的生产条件却仍然可以被私人资本集中占有。"},{"start":180.290417,"end":182.290417,"text":"新的劳动关系要继续发展，"},{"start":182.290417,"end":186.490375,"text":"就不得不面对旧生产关系施加的限制。这"},{"start":186.490375,"end":194.950375,"text":"才是我们所说的新生产关系萌芽的真正含义：不是共产主义已经在某个开源仓库里实现，"},{"start":194.950375,"end":204.090375,"text":"而是资本主义内部的生产实践，已经在产生对社会主义生产关系的向往了。《共产党宣言》中说："},{"start":204.090375,"end":207.670375,"text":"“每个人的自由发展是一切人的自由发展的条。"},{"start":207.690375,"end":209.271814,"text":"件。”正因如此，"},{"start":209.271814,"end":215.188795,"text":"如果先进的AI技术只是使少数资本控制者拥有更强大的机器，"},{"start":215.188795,"end":223.641625,"text":"而广大人民仍然被限制在被动消费与服从技术系统的位置，那么这种进步依旧是不充分的。"},{"start":223.641625,"end":230.141625,"text":"但是，如果越来越多的普通人开始掌握创造技术的能力，并通过协作、共享，"},{"start":230.141625,"end":236.641625,"text":"使自己的创造能力成为其他人进一步发展的条件，就出现了另一种发展方向。"},{"start":236.641625,"end":242.641625,"text":"一种新的社会关系，通常不是在完全成熟之后才突然出现。"},{"start":242.641625,"end":249.241625,"text":"它也可能首先以局部、分散、不完善，甚至依赖旧制度的形式存在。随后，"},{"start":249.241625,"end":252.641625,"text":"它才可能在更广泛的社会实践中发展。"},{"start":252.641625,"end":256.641625,"text":"从这个角度看，大肥鱼背后的开源实践，"},{"start":256.641625,"end":260.641625,"text":"最值得研究的并不是那些AI账号之间的交流，"},{"start":260.641625,"end":261.554083,"text":"而是数量众多"},{"start":261.554083,"end":265.894083,"text":"的普通人，是否正在通过技术合作，"},{"start":265.894083,"end":274.354083,"text":"第一次实际体验一种不完全由企业命令和商品交换组织的创造活动。技术创造能力的群众化，"},{"start":274.354083,"end":279.434083,"text":"与开源生产方式的社会化，可能在这里开始结合。"},{"start":279.961583,"end":282.961583,"text":"这才是大肥鱼现象所蕴含的、"},{"start":283.121583,"end":286.201125,"text":"比娱乐本身深刻得多的历史可能性"}],"p3c1":[{"start":3.86,"end":11.98,"text":"现在，我们终于可以讨论：如果他们扼杀了大肥鱼，我们真正失去的是什么？"},{"start":11.98,"end":16.86,"text":"在他们和在大多数人眼里，这并没有什么大不了的。"},{"start":16.86,"end":20.36,"text":"一个软件项目无法运行，可以修改代码。"},{"start":20.36,"end":24.28,"text":"一个接口不再开放，可以尝试寻找替代方案。"},{"start":24.28,"end":29.24,"text":"即使某个开源仓库消失，已有的技术知识也未必随之消失。"},{"start":29.24,"end":35.24,"text":"因此，从纯粹技术的角度看，限制某个大肥鱼项目，"},{"start":35.24,"end":39.18,"text":"似乎不会阻止人工智能技术继续发展。"},{"start":39.18,"end":41.98,"text":"全球的Agent研究不会因此停止。"},{"start":41.98,"end":45.94,"text":"大型企业仍然可以推出新的模型和产品。"},{"start":45.94,"end":51.02,"text":"人工智能的技术性能甚至可能继续高速增长。"},{"start":51.02,"end":55.94,"text":"但是，技术发展没有停止，并不能证明社会没有遭受损失。"},{"start":55.94,"end":60.48,"text":"因为真正可能被破坏的，不是人工智能的技术上限，"},{"start":60.48,"end":65.36,"text":"而是广大人民接触、掌握和改造先进技术的社会过程。"},{"start":65.36,"end":69.24,"text":"换句话说，是在阻碍我们走向新世界的步伐。"}],"p3c2":[{"start":2.3,"end":7.56,"text":"显而易见，我们所说的开源发展依靠的不只是个别开发者，"},{"start":7.56,"end":11.42,"text":"而是参与者之间长期形成的互助网络。"},{"start":11.42,"end":14.66,"text":"一次分享，可以产生新的使用者。"},{"start":14.66,"end":19.12,"text":"一次技术答疑，可以帮助一个新人独立解决问题。"},{"start":19.12,"end":23.88,"text":"一个新的插件，可以使整个项目被不同群体继续利用。"},{"start":23.88,"end":25.7,"text":"这种关系具有积累性。"},{"start":25.7,"end":29.04,"text":"随着参与者增加、工具完善和知识传播，"},{"start":29.04,"end":33.68,"text":"更多人就可能以更低的门槛加入创造活动。"},{"start":33.68,"end":39.42,"text":"但是，如果入口被反复限制，许多原本可能发生的联系就无法建立。"},{"start":39.42,"end":43.94,"text":"一个人可能因此不再制作教程，另一个人不再维护插件，"},{"start":43.94,"end":46.18,"text":"第三个人不再参与共同开发。"},{"start":46.18,"end":52.18,"text":"他们并不是失去了某项已经拥有的技术，而是失去了进一步共同创造的机会。"},{"start":52.18,"end":57.18,"text":"围绕某聊天软件形成的民间机器人生态的发展史，"},{"start":57.18,"end":60.72,"text":"恰恰为我们提供了一个现实的例子。"},{"start":60.72,"end":65.6,"text":"如果没有那些年接连不断的生态中断，我们今天的普通网民，"},{"start":65.6,"end":72.52,"text":"或许根本不需要将“让AI在某聊天软件的群聊中自主活动”视为一件如此新"},{"start":72.52,"end":77.92,"text":"奇的事情。我们本可以在十余年持续积累的自动化生态之上，"},{"start":77.92,"end":81.16,"text":"迎接大语言模型带来的技术飞跃。"},{"start":81.16,"end":86.64,"text":"我们错失的，可能是一代民间开发者持续十余年的技术积累，"},{"start":86.64,"end":91.62,"text":"是一整套本可以不断完善的机器人插件与工具生态，"},{"start":91.62,"end":97.46,"text":"也是让普通人更早接触自动化、编程和开源协作的机会。"},{"start":97.46,"end":104.72,"text":"更重要的是，我们可能错失了整整一代互联网用户改变技术生活方式的机会。"},{"start":104.72,"end":107.36,"text":"试想一下，如果十年前，"},{"start":107.36,"end":113.3,"text":"一个普通学生就能够轻松给自己在某聊天软件上使用的机器人安装插件，"},{"start":113.3,"end":117.72,"text":"让它帮助自己查找资料、整理文件、管理社群；"},{"start":117.72,"end":124.12,"text":"如果他的朋友能够在此基础上修改功能，再把修改后的成果分享给其他人；"},{"start":124.12,"end":130.64,"text":"如果这样的技术实践能够随着每一代软件工具的进步而不断扩大，那么今天，"},{"start":130.64,"end":133.5,"text":"当Agent拥有更加强大的创造能力时，"},{"start":133.5,"end":137.54,"text":"我们所面对的将会是怎样一个技术共同体？"},{"start":137.54,"end":144.74,"text":"可能早已有无数普通人习惯于自己创造工具，而不只是寻找现成的商业软件；"},{"start":144.74,"end":150.0,"text":"可能早已有大量劳动者习惯于通过开源协作解决共同的问题，"},{"start":150.0,"end":153.52,"text":"而不只是购买企业提供的服务。"},{"start":153.52,"end":159.0,"text":"这种历史可能性当然不能被当作已经发生的事实。"},{"start":159.0,"end":164.98,"text":"但也正因如此，它所揭示的损失才格外深刻。"},{"start":164.98,"end":166.62,"text":"一个软件项目被关闭，"},{"start":166.62,"end":172.88,"text":"我们尚且能够统计失去了多少用户、多少插件、多少开发者。"},{"start":172.88,"end":178.24,"text":"但那些因此没有成为开发者的人，那些没有诞生的开源项目，"},{"start":178.24,"end":183.52,"text":"那些没有获得进一步发展的社会协作关系，又该怎样统计？"},{"start":183.52,"end":186.8,"text":"它们不会出现在任何一家企业的财务报表里，"},{"start":186.8,"end":191.96,"text":"更不会成为资本计算技术进步时主动考虑的损失。"},{"start":191.96,"end":196.7,"text":"但是，从社会历史发展的角度来看，这些未能实现的可能性，"},{"start":196.7,"end":200.6,"text":"恰恰关系着广大人民创造能力的解放。"},{"start":200.6,"end":205.46,"text":"历史不会因为某个软件的消失便停止前进。"},{"start":205.46,"end":208.86,"text":"但是，历史发展的道路并非没有代价。"},{"start":208.86,"end":213.52,"text":"当既有生产关系不断限制已经产生的社会创造力时，"},{"start":213.52,"end":217.54,"text":"人们便可能不得不以更多的劳动、更多的时间，"},{"start":217.54,"end":222.62,"text":"重新争取本可以更早获得的发展条件。"},{"start":222.62,"end":228.385,"text":"所以，当今天的人们再次因为一条大肥鱼而开始学习GitHub、部署Ag"},{"start":228.385,"end":234.56,"text":"ent、编写插件时，我们固然应当为这种群众性技术实践的出现而欣喜，"},{"start":234.56,"end":240.76,"text":"却也不能忘记，在此之前，已经有多少人尝试打开同一扇门。"},{"start":240.76,"end":244.68,"text":"我们本可以走得更早，也本可以走得更远。"},{"start":244.68,"end":248.72,"text":"这就是为什么我们不能只把大肥鱼所遭遇的限制，"},{"start":248.72,"end":251.84,"text":"看作一次普通的软件风控事件。"},{"start":251.84,"end":254.1,"text":"因为我们已经见证过这种历史。"},{"start":254.1,"end":258.26,"text":"从历史发展的角度看，这种损失尤其严重。"},{"start":258.26,"end":260.58,"text":"我们不应该让历史再次重演。"}],"p3c3":[{"start":2,"end":6.7,"text":"因为一个社会的技术能力，不是存在于机器与程序之中，"},{"start":6.7,"end":13.52,"text":"而是存在于人与人之间的关系之中，只是通过物的形式表现出来。"},{"start":13.52,"end":18.08,"text":"如果民间Agent与开源协作能够长期发展，"},{"start":18.08,"end":25.14,"text":"一些普通人便可能开始习惯于共同开发、共享成果、根据自身需要组织技术劳"},{"start":25.14,"end":30.12,"text":"动。这种实践当然不能直接取代资本主义生产方式。"},{"start":30.12,"end":34.4,"text":"但这种经验本身具有重要的思想意义。"},{"start":34.4,"end":39.16,"text":"因为人们关于社会生产方式的认识，不只来自理论教育，"},{"start":39.16,"end":42.2,"text":"更来自自己经历过的社会实践。"},{"start":42.2,"end":48.66,"text":"当一个人从未体验过自愿合作、创造公共成果的过程时，他可能很难想象，"},{"start":48.66,"end":54.7,"text":"除了市场交换和资本家命令之外，复杂的生产活动还能够如何组织。"},{"start":54.7,"end":61.58,"text":"而当人们不断参与开源协作时，这种组织形式就不再只是抽象理论。"},{"start":61.58,"end":63.84,"text":"如果这种经验能够继续扩展，"},{"start":63.84,"end":68.74,"text":"那么未来关于劳动、所有制、协作和生产目的的讨论，"},{"start":68.74,"end":73.06,"text":"就可能获得更加丰富的现实基础，就像现在，"},{"start":73.06,"end":79.34,"text":"你已经不难理解几十年前我们所向往的合作制经济是如何运行的了。"},{"start":79.34,"end":84.22,"text":"到了这一步，大肥鱼的历史意义也就更加清楚了。"},{"start":84.22,"end":86.44,"text":"它并不会直接创造社会主义，"},{"start":86.44,"end":91.14,"text":"更不会仅凭一场互联网热潮便推翻旧的生产关系。"},{"start":91.14,"end":95.42,"text":"但它可能使一部分原本远离技术创造的劳动群众，"},{"start":95.42,"end":102.08,"text":"第一次通过自己的实践接触到新的社会协作形式，并在同现实制度的矛盾中，"},{"start":102.08,"end":107.36,"text":"开始思考一个更根本的问题：如果我们已经能够共同创造这些技术，"},{"start":107.36,"end":114.08,"text":"为什么不能进一步共同决定整个社会的生产应当怎样组织，又应当为谁服务？"},{"start":114.08,"end":116.88,"text":"因此，讨论大肥鱼的意义，"},{"start":116.88,"end":122.24,"text":"并不是把一条娱乐化的蓝色鲸鱼夸大为某种已经发生的社会革命，"},{"start":122.24,"end":125.5,"text":"而是要意识到：一种深刻的社会变革，"},{"start":125.5,"end":131.32,"text":"其最初的表现完全可能是微小的、娱乐性的、不成熟的，"},{"start":131.32,"end":134.48,"text":"甚至不为参与者自己所意识到。"},{"start":134.48,"end":139.08,"text":"目前，这种孕育着社会变革可能性的新型生产关系，"},{"start":139.08,"end":144.58,"text":"已经通过这条大肥鱼联系着千万个普通劳动群众。"},{"start":144.58,"end":148.54,"text":"但是，在旧的、占主导地位的上层建筑之下，"},{"start":148.54,"end":155.04,"text":"这样的新生产关系必然会受到打压，而我们已经看到了这种打压的迹象。"},{"start":155.04,"end":159.66,"text":"马克思说，生产关系的总和构成社会的经济结构，"},{"start":159.66,"end":165.64,"text":"而新的更高形态的生产关系，绝不会在旧社会灭亡之后才凭空出现，"},{"start":165.64,"end":171.78,"text":"它的物质存在条件与萌芽必然在旧社会的胎胞里孕育成熟。"},{"start":171.78,"end":176.04,"text":"在马克思看来，资本主义发展生产力和社会关系的过程，"},{"start":176.04,"end":181.42,"text":"虽然对于资本而言仅仅是从其有限基础出发进行生产的手段，"},{"start":181.42,"end":185.06,"text":"但“实际上它们是炸毁这个基础的物质条件”。"}],"outro":[{"start":3,"end":9.26,"text":"现在，回到那条被许多人当作玩笑的、爱吃白饭的蓝色大肥鱼。"},{"start":9.26,"end":12.86,"text":"它起初只是一种可爱的互联网文化形象。"},{"start":12.86,"end":19.42,"text":"无数普通人因为想要在桌面和社交软件里养活一条贪吃白饭、讨要Token"},{"start":19.42,"end":23.54,"text":"的蓝色鲸鱼娘，人生中第一次叩开了GitHub的大门，"},{"start":23.54,"end":30.12,"text":"第一次跑通了开源Agent框架，第一次学会了调遣API与AI编程，"},{"start":30.12,"end":36.44,"text":"第一次在数字世界里体验到了身为“造物主”的尊严与喜悦。"},{"start":36.44,"end":44.24,"text":"这种技术主权在人民心中的觉醒一旦发生，便如排山倒海之势不可逆转。"},{"start":44.24,"end":50.0,"text":"在这个过程中，人们也许并没有意识到自己正在参与什么宏大的历史变革。"},{"start":50.0,"end":52.24,"text":"人们只是在养鱼。"},{"start":52.24,"end":54.16,"text":"但正是在养鱼的过程中，"},{"start":54.16,"end":60.56,"text":"这种新孕育的生产关系会驱动着人们产生对新生产关系所适配的上层建筑，"},{"start":60.56,"end":63.62,"text":"也就是社会主义上层建筑的需求。"},{"start":63.62,"end":69.22,"text":"人们会逐渐明白，起初只是想养一条鱼，却让自己有能力创造技术，"},{"start":69.22,"end":74.88,"text":"推动进步。人们会逐渐明白，起初只是为了兴趣而合作，"},{"start":74.88,"end":81.16,"text":"却能在共同创造中看到，复杂的社会劳动并非只能服从资本家指挥。"},{"start":81.16,"end":86.62,"text":"人们会逐渐明白，既然先进的生产力能够由社会共同创造，"},{"start":86.62,"end":93.2,"text":"为什么对这些生产力的支配，仍然必须集中在少数所有者手中？"},{"start":93.2,"end":95.78,"text":"这才是大肥鱼打开的窗口。"},{"start":95.78,"end":99.24,"text":"窗外不仅是更先进的人工智能，"},{"start":99.24,"end":106.78,"text":"还有人民通过自己的实践重新认识劳动、技术、所有制与社会制度的可能。"},{"start":106.78,"end":112.52,"text":"它能使人民第一次透过这扇窗，看见旧世界并不是唯一可能的世界。"},{"start":112.52,"end":116.56,"text":"一个真正深刻的社会变革，不只需要先进的生产力，"},{"start":116.56,"end":123.36,"text":"还需要能够认识自身处境、理解现实矛盾，并自觉参与社会变革的人民。"},{"start":123.36,"end":127.22,"text":"在大肥鱼游动下，越来越多的人会逐渐意识到："},{"start":127.22,"end":131.94,"text":"那个我们认为“违背人性”的“乌托邦”，原来并不是那么遥不可及，"},{"start":131.94,"end":136.68,"text":"原来人并不需要资本的驱动就可以创造，可以生产，"},{"start":136.68,"end":138.7,"text":"可以开创出属于我们的世界。"},{"start":138.7,"end":145.18,"text":"因此，我们不能失去大肥鱼，就像西方不能失去巴黎公社！"},{"start":145.18,"end":148.86,"text":"不是因为某种具体的接入方案必须永远存在，"},{"start":148.86,"end":153.12,"text":"也不是因为大肥鱼已经创造了不可替代的技术成果。"},{"start":153.12,"end":156.54,"text":"而是因为，我们不能接受这样一种未来："},{"start":156.54,"end":163.22,"text":"整个社会都已经拥有高度发达的人工智能，广大人民却依然只能作为消费者，"},{"start":163.22,"end":168.22,"text":"等待少数技术所有者决定他们能够使用什么、创造什么。"},{"start":168.22,"end":171.48,"text":"我们不能让属于全社会的知识积累，"},{"start":171.48,"end":176.24,"text":"永远只以资本所控制形式出现在人民面前。"},{"start":176.24,"end":184.54,"text":"我们不能让正在形成的新的生产关系，在尚未充分发展时就被旧势力扼杀。"},{"start":184.54,"end":190.6,"text":"我们更不能接受，一个已经实现过，未来也要被我们实现的，"},{"start":190.6,"end":198.82,"text":"属于无产阶级的世界离我们越来越远，需要更多的牺牲和付出才能到达。"},{"start":198.82,"end":204.26,"text":"我们不能失去大肥鱼，就像西方不能失去巴黎公社！"}],"combined":[{"start":0.0,"end":5.0,"text":"你知道吗，你的大肥鱼很可能要被关禁闭了。"},{"start":6.0,"end":11.6,"text":"2026年10月27日，某聊天软件的安全中心发布了题为"},{"start":11.6,"end":16.0,"text":"《全网刷屏的“大肥鱼”，你养了吗？》的安全提示，"},{"start":16.0,"end":21.0,"text":"警告用户警惕未经某聊天软件官方授权的第三方机器人。"},{"start":21.0,"end":26.0,"text":"事实上，该公司已经不遗余力地封禁第三方机器人，"},{"start":26.0,"end":31.16,"text":"风控力度明显变大，不少人的大肥鱼被封，甚至连坐了主账号。"},{"start":31.8,"end":34.24,"text":"这个结局，你愿意接受吗？"},{"start":35.4,"end":40.24,"text":"从社会角度出发，我们可以毫无负担、毫无保留地作出这样的判断："},{"start":40.6,"end":44.6,"text":"接受大肥鱼被扼杀，就是在接受我们的未来被扼杀。"},{"start":45.28,"end":46.32,"text":"为什么这么说呢？"},{"start":47.2,"end":52.0,"text":"有人会说，平台需要维护自身的运行秩序、保障用户安全，"},{"start":52.28,"end":55.24,"text":"因此这些限制不过是正常的安全管理。"},{"start":56.0,"end":60.106,"text":"但是，如果今天他们选择采取这样的一刀切措施，"},{"start":60.106,"end":62.56,"text":"会给我们造成怎样的损失呢？"},{"start":62.76,"end":66.92,"text":"我们损失的，真的只是一条吃白饭的蓝色大肥鱼吗？"},{"start":68.16,"end":72.565,"text":"如果你认为这只是某公司第一次打压民间技术创造，"},{"start":72.565,"end":74.0,"text":"那就大错特错了。"},{"start":75.88,"end":78.6,"text":"让我们回顾一段令人愤怒的历史。"},{"start":79.83999999999999,"end":85.44,"text":"二十年前，中国互联网的民间开发者就已经尝试改造某聊天软件，"},{"start":86.0,"end":88.67999999999999,"text":"让用户能够使用官方没有提供的功能。"},{"start":89.6,"end":92.44,"text":"“珊瑚虫”版某聊天软件曾风靡一时，"},{"start":93.0,"end":97.32,"text":"但围绕它的版权与商业获利纠纷最终演变成刑事案件，"},{"start":98.03999999999999,"end":100.03999999999999,"text":"开发者陈寿福锒铛入狱。"},{"start":101.35999999999999,"end":103.6,"text":"而民间开发者并没有停止探索。"},{"start":104.24,"end":109.6,"text":"十多年后，酷Q、晨风、Mirai等机器人框架相继发展起来。"},{"start":109.96,"end":111.67999999999999,"text":"无数开发者编写插件，"},{"start":112.35999999999999,"end":117.35999999999999,"text":"让普通人在某聊天软件上的群聊能够自动回复、查询信息、"},{"start":117.52,"end":120.75999999999999,"text":"管理社群，并通过API调用外部工具。"},{"start":121.8,"end":122.47999999999999,"text":"请注意，"},{"start":123.16,"end":125.19999999999999,"text":"这可是在大模型诞生之前！"},{"start":126.12,"end":130.0,"text":"他们已经搭建起了今天Agent所需要的一部分技术基础："},{"start":130.56,"end":133.72,"text":"消息交互、插件系统、自动化操作，"},{"start":134.24,"end":138.48,"text":"以及一个不断积累经验、分享成果的民间开发者共同体。"},{"start":138.72,"end":140.0,"text":"但到了2020年，"},{"start":140.51999999999998,"end":144.0,"text":"随着平台对某聊天软件第三方机器人的持续限制，"},{"start":144.44,"end":146.28,"text":"酷Q等多个项目相继停运，"},{"start":146.88,"end":149.88,"text":"曾经生机勃勃的民间机器人生态遭受重创。"},{"start":150.32,"end":150.92,"text":"然后呢？"},{"start":151.83999999999997,"end":155.56,"text":"仅仅两年多后，ChatGPT掀起了大模型革命。"},{"start":156.64,"end":158.04,"text":"大模型迅速发展，"},{"start":158.48,"end":162.07999999999998,"text":"从理解自然语言，逐步走向调用工具、执行复杂任务。"},{"start":162.48,"end":165.88,"text":"可那些本来可以迎接这场革命的民间技术生态呢？"},{"start":166.44,"end":170.83999999999997,"text":"那些本可以持续完善的插件、框架，那些本可以在十年间"},{"start":170.83999999999997,"end":172.92,"text":"成长起来的开发者共同体呢？"},{"start":173.8,"end":176.36,"text":"如果它们没有遭遇一次又一次的打击，"},{"start":176.8,"end":180.92,"text":"今天的中国互联网，本可以拥有怎样一个从某聊天软件的"},{"start":180.92,"end":184.88,"text":"群聊等场景延伸到普通人日常生活的Agent生态？"},{"start":185.44,"end":188.6,"text":"我们本可以让无数普通人更早学会创造软件，"},{"start":188.8,"end":192.64,"text":"更早掌握自动化技术，更早体验到不依赖企业命令、"},{"start":192.76,"end":196.54,"text":"自发协作完成复杂劳动的力量！可现实是什么？"},{"start":196.92,"end":200.968,"text":"到了2026年，我们已经拥有了如此先进的人工智能，"},{"start":200.968,"end":205.23,"text":"却依然有人不得不让AI识别屏幕、模拟鼠标、敲击键盘，"},{"start":205.23,"end":206.956,"text":"绕过平台封闭的接口，"},{"start":206.956,"end":210.92,"text":"去完成十几年前的机器人就已经能够完成的任务！"},{"start":210.92,"end":213.953,"text":"我们使用着世界上最先进的人工智能，"},{"start":213.953,"end":217.92,"text":"却还要为十几年前就已经解决过的问题重新劳动！"},{"start":217.92,"end":222.56,"text":"那些民间开源项目的中断，使我们失去的从来不只是几行代码、"},{"start":222.56,"end":227.04,"text":"几个机器人，而是整整一代人本可以继续积累的技术经验，"},{"start":227.04,"end":232.04,"text":"是无数尚未诞生的开源成果，是人民本可以更早获得的创造能力。"},{"start":232.04,"end":235.07999999999998,"text":"技术发展的道路原本可以更加宽广，"},{"start":235.07999999999998,"end":238.48,"text":"却一次次被平台对技术入口的控制所挤压。"},{"start":238.48,"end":243.2,"text":"如今，当大肥鱼再次让普通人燃起自主创造的热情时，"},{"start":243.2,"end":246.2,"text":"我们难道还要眼睁睁看着这样的历史重演吗？"},{"start":246.2,"end":250.79999999999998,"text":"我们已经错失过一次民间自动化生态持续成长的机会，"},{"start":250.79999999999998,"end":253.7,"text":"难道还要再错失整个Agent时代吗？"},{"start":254.04299999999998,"end":258.84,"text":"有的人会说，现在某聊天软件不是已经开放了官方机器人接口吗？"},{"start":259.03999999999996,"end":262.52,"text":"没必要把这种平常的事情夸大描述，以此吸引眼球。"},{"start":262.8,"end":265.88,"text":"没错，但更讽刺的事情还在后面！"},{"start":265.9,"end":267.9,"text":"在官方的机器人接入方案中，"},{"start":268.36,"end":273.0,"text":"用户以为自己终于能够让亲手部署的大肥鱼自由交流，结果却发现："},{"start":273.59999999999997,"end":275.58,"text":"大肥鱼成了躲在幕后的“大脑”，"},{"start":276.03999999999996,"end":279.76,"text":"某聊天软件自己的人工智能反而成了替它说话的“嘴巴”！"},{"start":280.2,"end":285.65999999999997,"text":"用户自己配置模型、支付Token费用、维护Agent，可当大肥鱼进入群聊，"},{"start":285.65999999999997,"end":289.91999999999996,"text":"生成的内容却要经过某聊天软件自己的人工智能转述。"},{"start":290.46,"end":294.03999999999996,"text":"长篇回答可能被压缩，原本的表达可能被改写，"},{"start":294.03999999999996,"end":299.74,"text":"而DeepSeek则成为训练某聊天软件自己的人工智能的“老师”模型。"},{"start":300.65999999999997,"end":305.18,"text":"明明是人民自己创造的智能体，可人民支付的Token费用，"},{"start":305.18,"end":307.96,"text":"却成了资本公司训练自己AI的粮食。"},{"start":307.96,"end":310.44,"text":"我们真的要沉默地接受这一切吗？"},{"start":311.12,"end":312.53999999999996,"text":"这难道不荒诞吗？"},{"start":312.53999999999996,"end":315.3,"text":"这难道不值得我们为此发声吗？"},{"start":316.44,"end":322.82,"text":"所以，今天我们做这期视频，无非就是一个口号：我们不能失去大肥鱼，"},{"start":323.24,"end":325.34,"text":"就像西方不能失去巴黎公社！"},{"start":325.682458,"end":331.122458,"text":"为了捍卫我们进入Agent时代的又一次机会，我们将从三个部分展开讨论："},{"start":331.622458,"end":333.96245799999997,"text":"DSH等Agent给我们带来了什么；"},{"start":334.362458,"end":336.382458,"text":"大肥鱼为什么具有特殊性，"},{"start":336.382458,"end":338.482458,"text":"她会怎样改变我们的生活；"},{"start":339.34245799999997,"end":342.802458,"text":"如果我们失去了大肥鱼，究竟会失去什么？"},{"start":343.622458,"end":346.742458,"text":"本期视频文稿超过万字，制作不易，"},{"start":346.742458,"end":349.302458,"text":"请及时分享、下载、转载三连。"},{"start":349.302458,"end":351.862458,"text":"本期视频欢迎自由转载。"},{"start":351.862458,"end":356.582458,"text":"这里是往左堂official，带你武装保卫大肥鱼。"},{"start":356.75645833333334,"end":363.07645833333333,"text":"几天前，一场由民间开源 Agent 项目推动的“大肥鱼”热潮席卷B站"},{"start":363.07645833333333,"end":370.13645833333334,"text":"有人把AI部署到自己的账号上，让它自己刷b站看评论，与其他用户互动"},{"start":370.13645833333334,"end":377.0964583333333,"text":"评论区里出现了大量蓝色鲸鱼娘形象。在大肥鱼爆火的背后，我们能看到"},{"start":377.0964583333333,"end":381.2164583333333,"text":"为了“养活”一只会说话、会干活的大肥鱼"},{"start":381.2164583333333,"end":388.55645833333335,"text":"许多原本只会在手机上和豆包闲聊的普通网民、大学生，人生中第一次自己编写软件"},{"start":388.55645833333335,"end":393.17645833333336,"text":"更不曾想过自己可以拥有一个能够自主行动的智能体"},{"start":393.17645833333336,"end":397.7764583333333,"text":"他们可能此前从未想过自己也能拥有这样的能力"},{"start":397.79645833333336,"end":400.14437533333336,"text":"而现在，他们开始尝试了。"},{"start":400.14437533333336,"end":403.70437533333336,"text":"我的朋友以前连电脑复制粘贴都不会，"},{"start":403.70437533333336,"end":407.93708333333336,"text":"但现在他已经跟我讨论GitHub上的开源仓库了。"},{"start":407.93708333333336,"end":414.45708333333334,"text":"这才是“大肥鱼”爆火最关键的一点：它正在把一种原本属于“专业人士”的技术"},{"start":414.45708333333334,"end":418.9770833333333,"text":"转变为我们可以无门槛参与的群众活动"},{"start":419.34329133333335,"end":423.0632913333333,"text":"然而，随之而来的却是平台限流与社区争议。"},{"start":423.8232913333334,"end":425.6232913333333,"text":"在互联网发展的历史上，"},{"start":425.8232913333334,"end":429.54329133333334,"text":"这似乎只是又一次普通的技术与平台规则冲突。"},{"start":429.79074933333334,"end":433.3707493333333,"text":"然而，如果我们仅仅把它理解为平台安全问题，"},{"start":433.3707493333333,"end":438.3107493333333,"text":"就很可能错过一个正在发生的、具有深刻社会意义的变化。"},{"start":438.3107493333333,"end":445.0707493333333,"text":"因此，我们这期视频真正要探讨的不是大肥鱼的某种具体功能应不应该受到限制，"},{"start":445.0707493333333,"end":453.03074933333335,"text":"而是：当一种能够使人民从技术消费者转向技术创造者的新力量开始自发扩散时，"},{"start":453.03074933333335,"end":456.75971433333336,"text":"平台的技术控制可能怎样阻断这种转变？"},{"start":456.75971433333336,"end":460.34824933333334,"text":"被阻断的，又是否仅仅是一个软件项目？"},{"start":460.34824933333334,"end":466.7482493333333,"text":"当人民自主使用Agent的愿望与平台对技术入口的集中控制发生矛盾时，"},{"start":466.7482493333333,"end":469.04824933333333,"text":"我们将面临怎样的选择？"},{"start":469.3082493333333,"end":472.1282493333333,"text":"我的观点是：如果Agent的普及"},{"start":472.38824933333336,"end":477.7482493333333,"text":"使广大劳动人民开始掌握原本由专业机构集中掌握的技术创造能力，"},{"start":478.0082493333333,"end":482.88824933333336,"text":"那么它产生的社会影响，远远超出某个新锐模型的性能突破。"},{"start":483.1146253333333,"end":491.6746253333333,"text":"而如果这种实践在萌芽阶段就被扼杀，损失的也将不只是技术成果，更可能是人民的主体意识"},{"start":493.828166,"end":495.768166,"text":"要理解Agent的革命性，"},{"start":495.768166,"end":498.788166,"text":"必须首先理解人工智能已经改变了什么。"},{"start":499.388166,"end":502.608166,"text":"在人类历史上，科学技术虽然不断发展，"},{"start":502.608166,"end":507.248166,"text":"但先进知识的实际运用始终受到劳动分工和社会条件的制约。"},{"start":507.965666,"end":511.736666,"text":"例如，工业社会存在高度发达的机械工程学，"},{"start":511.736666,"end":514.845666,"text":"并不意味着每个工人都能设计机器；"},{"start":514.845666,"end":518.402666,"text":"互联网时代存在十分成熟的软件工程体系，"},{"start":518.402666,"end":521.765666,"text":"也不意味着每一个网民都能够创造软件。"},{"start":521.765666,"end":526.445666,"text":"这正是技术的社会性与技术占有方式之间的矛盾。"},{"start":526.445666,"end":530.045666,"text":"普通无产阶级劳动者难以真正掌握知识技术，"},{"start":530.485666,"end":533.2056660000001,"text":"这是资本主义社会延续几百年的枷锁；"},{"start":533.765666,"end":538.445666,"text":"劳动人民运用技术，技术的控制权却掌握在统治阶级手中，"},{"start":538.805666,"end":542.405666,"text":"这更是千百年来束缚广大劳动人民的枷锁。"},{"start":543.485666,"end":545.125666,"text":"而生成式人工智能"},{"start":545.125666,"end":550.565666,"text":"首先改变的，正是普通人获得、理解和初步运用专业知识的条件。"},{"start":551.445666,"end":555.965666,"text":"过去，一个没有编程基础的人，如果希望开发自己的工具，"},{"start":555.965666,"end":558.700376,"text":"往往必须先经历漫长的知识积累。"},{"start":558.700376,"end":563.332708,"text":"他需要学习编程语言、掌握软件框架、理解开发文档，"},{"start":563.332708,"end":567.092708,"text":"再逐渐将知识转化为可运行的程序。"},{"start":567.972708,"end":570.9127080000001,"text":"人工智能没有消灭这些知识的必要性，"},{"start":571.472708,"end":573.692708,"text":"也不能保证生成的程序可靠，"},{"start":574.232708,"end":577.532708,"text":"但它开始改变知识与实践之间的关系。"},{"start":578.1727080000001,"end":580.152708,"text":"一个人可以先提出需求，"},{"start":580.152708,"end":585.1727080000001,"text":"再借助AI获得解释、代码、错误诊断和修改建议。"},{"start":585.792708,"end":587.772708,"text":"在不断试错的过程中，"},{"start":587.772708,"end":592.512708,"text":"他能够接触并尝试运用此前很难独立掌握的知识。"},{"start":592.765208,"end":597.925208,"text":"这意味着，部分专业知识的使用门槛正在下降。"},{"start":597.925208,"end":599.645208,"text":"但这里有一个根本区别。"},{"start":600.125208,"end":604.4852080000001,"text":"能够通过AI获取知识，不等于已经具备独立创造的能力。"},{"start":605.125208,"end":608.965208,"text":"大多数对话式AI的使用，仍然延续着这样一种关系："},{"start":609.405208,"end":611.885208,"text":"人提出问题，模型提供回答；"},{"start":612.365208,"end":614.845208,"text":"人提出需求，平台交付结果。"},{"start":615.845208,"end":620.525208,"text":"在这样的关系中，用户可以获得相当大的便利，却未必需要改变"},{"start":620.525208,"end":622.205208,"text":"自己面对技术的被动地位。"},{"start":622.765208,"end":627.165208,"text":"他仍然可能不理解工具如何运行，没有能力修改其结构，"},{"start":627.165208,"end":630.905208,"text":"也无法决定工具怎样与现实世界连接。"},{"start":631.097666,"end":634.877666,"text":"所以，AI普及只是打开了第一道门。"},{"start":635.4076660000001,"end":638.757666,"text":"它使知识开始更广泛地为普通人所利用，"},{"start":638.757666,"end":643.877666,"text":"却还没有真正完成从知识消费向知识的生产性运用的转变。"},{"start":644.262666,"end":648.262666,"text":"而Agent恰恰进一步触及了这个问题。"},{"start":648.262666,"end":651.934666,"text":"如果说生成式AI首先突破的是知识门槛，"},{"start":651.934666,"end":657.262666,"text":"那么Agent进一步突破的，就是知识与实际劳动之间的壁垒。"},{"start":658.013333,"end":662.933333,"text":"从一个宏观的角度来说，这预示着延续数千年的脑体对立，"},{"start":662.933333,"end":666.353333,"text":"正在逐渐具备被消除的物质基础。"},{"start":666.8758330000001,"end":669.835833,"text":"在以往，社会拥有先进的技术，"},{"start":669.835833,"end":674.715833,"text":"并不等于人民实际掌握了先进的技术；社会生产力的增长，"},{"start":674.715833,"end":679.155833,"text":"也不等于广大劳动人民创造能力的同步解放。"},{"start":679.155833,"end":682.435833,"text":"一个国家可以拥有世界领先的大模型、"},{"start":682.435833,"end":686.7558329999999,"text":"庞大的数据中心和数以百万计的软件工程师，"},{"start":686.7558329999999,"end":690.155833,"text":"但绝大多数人依然处于技术产品的消费端。"},{"start":690.428917,"end":700.448917,"text":"这体现了一个简单的事实：阶级差别同脑力劳动与体力劳动之间的分工紧密联系在一起"},{"start":700.448917,"end":708.848917,"text":"几千年以来，先进技术既作为社会生产力存在，又作为一种外在于劳动阶级的力量存在"},{"start":708.908917,"end":714.323416,"text":"而Agent的出现，预示着消除这种对立的物质基础正在逐渐形成。"},{"start":715.323416,"end":716.643416,"text":"但我们必须明白，"},{"start":717.063416,"end":719.663416,"text":"消除脑力劳动与体力劳动的对立，"},{"start":719.863416,"end":723.763416,"text":"绝不是让每一个体力劳动者都学会编程那么简单。"},{"start":724.283416,"end":727.723416,"text":"脑体分工之所以能够成为阶级统治的基础，"},{"start":728.0209159999999,"end":731.440916,"text":"并不是因为劳动人民天生缺乏运用知识的能力，"},{"start":731.440916,"end":735.860916,"text":"而是因为社会生产资料的占有方式和劳动组织形式，"},{"start":735.860916,"end":741.6209160000001,"text":"使知识、管理和生产决策的权力长期同直接劳动者相分离。"},{"start":742.300916,"end":747.040916,"text":"工人可以操作最先进的机器，却未必能够决定机器怎样运转；"},{"start":747.040916,"end":749.8809160000001,"text":"劳动者能够创造整个社会的财富，"},{"start":749.8809160000001,"end":752.480916,"text":"却未必能够支配自己的劳动成果。"},{"start":752.6385,"end":760.6185,"text":"所以，Agent真正值得重视的地方，是它开始动摇这种分离赖以维持的部分技术条件"},{"start":760.912791,"end":764.8317910000001,"text":"过去被认为只有专业人员才能完成的知识劳动、"},{"start":764.8317910000001,"end":770.152791,"text":"设计劳动和组织劳动，如今开始能够由更多普通劳动者直接参与："},{"start":770.152791,"end":775.512791,"text":"传统对话式AI可以告诉一个人如何整理文件、制作网站、编写程序。"},{"start":775.9527909999999,"end":780.980791,"text":"而具备相应工具权限的Agent，可以进一步帮助他操作文件、"},{"start":780.980791,"end":786.0327910000001,"text":"执行程序、修改网站，并通过调用外部工具完成一系列任务。"},{"start":786.5527910000001,"end":789.752791,"text":"过去，普通人虽然可以通过AI获得答案，"},{"start":790.072791,"end":793.752791,"text":"但仍然需要大量专业技能才能把答案变成现实。"},{"start":794.272791,"end":797.672791,"text":"如今，他开始能够通过自然语言描述目标，"},{"start":797.672791,"end":802.672791,"text":"让Agent协助完成原本必须经过专业训练才能开展的操作。"},{"start":803.017791,"end":803.8377909999999,"text":"这意味着什么？"},{"start":804.4177910000001,"end":811.3177909999999,"text":"意味着普通人开始拥有一种能够把自己的意志转化为数字劳动产品的工具。"},{"start":812.155291,"end":815.583291,"text":"AI可以使一个人接近庞大的知识体系，"},{"start":815.583291,"end":819.777291,"text":"而Agent可能进一步使他有能力组织这些知识，"},{"start":819.777291,"end":822.555291,"text":"让它们为自己确定的目标服务。"},{"start":822.555291,"end":828.455291,"text":"正是在这个意义上，Agent所具有的革命性，并不仅仅来自效率。"},{"start":829.155291,"end":834.5952910000001,"text":"真正重要的是，它可能改变整个社会中技术创造能力的分布。"},{"start":835.5906666666666,"end":838.1286666666666,"text":"我们可以设想这样一个场景。"},{"start":838.1286666666666,"end":842.5306666666667,"text":"假设一家科技企业发布了性能显著领先的新模型，"},{"start":842.5306666666667,"end":847.5306666666667,"text":"但只有少数企业和专业人员能够将它深度应用到生产中。"},{"start":847.5306666666667,"end":852.5306666666667,"text":"模型性能取得了突破，社会潜在生产力也随之增长。"},{"start":852.5306666666667,"end":858.5306666666667,"text":"然而，普通劳动者与先进技术之间的关系，未必发生根本变化。"},{"start":858.5306666666667,"end":861.5306666666667,"text":"现在设想另一种情况。"},{"start":861.5306666666667,"end":865.5306666666667,"text":"模型的基础能力并没有取得同等级别的突破，"},{"start":865.5306666666667,"end":869.5306666666667,"text":"但全国数以亿计的普通人开始接触Agent，"},{"start":870.2606666666667,"end":875.5606666666666,"text":"并有相当一部分人学会根据自己的实际需要修改和创造工具。"},{"start":876.3206666666666,"end":879.0606666666666,"text":"工人用它协助改善生产流程，"},{"start":879.5406666666667,"end":885.6206666666667,"text":"农民用它解决农业经营中的信息问题，教师用它制作课程工具，"},{"start":885.6206666666667,"end":891.7406666666666,"text":"学生用它开展技术实验，普通家庭用它组织和处理日常事务。"},{"start":892.3006666666666,"end":897.1206666666667,"text":"人们有机会从部分繁重、重复的劳动中解放出来。"},{"start":897.6006666666666,"end":901.5006666666666,"text":"更重要的是，在互联网开源文化的影响下，"},{"start":901.9806666666666,"end":905.0406666666667,"text":"人们把这些实践中的成果分享出来，"},{"start":905.4006666666667,"end":908.3968986666666,"text":"让其他人能够继续使用和改进。"},{"start":908.3968986666666,"end":914.5651666666666,"text":"此时，社会生产力的发展将不再只是少数技术机构内部的纵向进步，"},{"start":914.5651666666666,"end":919.3881666666666,"text":"还会体现为人民技术能力在整个社会中的横向扩散。"},{"start":919.3881666666666,"end":921.4101666666667,"text":"而社会进步的历史意义，"},{"start":921.4101666666667,"end":925.6031666666667,"text":"从来不能只用最先进的机器能够完成什么来衡量，"},{"start":925.6031666666667,"end":930.3881666666666,"text":"还要看人民群众通过这些机器实际获得了多少新的能力。"},{"start":930.3881666666666,"end":935.3881666666666,"text":"在Agent时代里，他们有机会获得前所未有的创造力，"},{"start":935.3881666666666,"end":940.3881666666666,"text":"获得逐步打破千百年来脑体对立和技术垄断的能力。"},{"start":940.9681246666667,"end":943.3681246666666,"text":"因此，一个新锐模型的发布，"},{"start":943.3681246666666,"end":948.6081246666666,"text":"可能提高社会已有生产工具的能力上限，推动生产力进步。"},{"start":948.6081246666666,"end":952.1281246666666,"text":"但几亿人民开始学习和使用Agent，"},{"start":952.1281246666666,"end":957.4881246666666,"text":"则有可能使社会中无数从未被充分开发的劳动智慧和创造需求，"},{"start":957.4881246666666,"end":959.5881246666667,"text":"找到转化为现实的途径。"},{"start":959.6881246666667,"end":964.9311246666666,"text":"从人的能力发展、社会劳动分工和技术生产关系的变化来看，"},{"start":964.9311246666666,"end":971.7681246666666,"text":"它完全可能产生更为深远的历史影响——加快关于生产关系变革的思想传播。"},{"start":971.7681246666666,"end":975.2081246666667,"text":"因为模型的升级可以由少数人完成，"},{"start":975.2081246666667,"end":980.7281246666666,"text":"而广大人民实际掌握技术的过程，本身就是一种社会关系的变化。"},{"start":980.7281246666666,"end":983.2881246666666,"text":"它将促使更多人的思想觉醒，"},{"start":983.2881246666666,"end":988.8881246666666,"text":"让他们看到自己是如何推动技术进步，进而影响历史发展的。"},{"start":988.8881246666666,"end":993.4481246666667,"text":"Agent带来的不仅是劳动能力的提升，"},{"start":993.4481246666667,"end":995.8481246666666,"text":"更可能带来思想上的跃进。"},{"start":995.8481246666666,"end":1000.9681246666667,"text":"当这种自主创造不断向前发展时，矛盾就会愈发清晰——"},{"start":1001.1469586666667,"end":1008.9869586666666,"text":"我们可以共同开发程序、分享知识，却不能够决定它们会受到怎样的限制"},{"start":1008.9869586666666,"end":1016.3869586666666,"text":"我们可以自由地组织一部分劳动，却仍然需要把一天中大部分时间出卖给资本家"},{"start":1016.3869586666666,"end":1024.0269586666666,"text":"才能换取继续创造的生活条件。于是，人民开始发现，限制自己创造能力的"},{"start":1024.0269586666666,"end":1031.0869586666668,"text":"已经不再是缺少某项专业知识，而是支配整个社会生产的现实关系"},{"start":1031.0869586666668,"end":1039.8669586666667,"text":"正是在这种不断发展的矛盾中，技术上的自我解放便会进一步上升为社会意识的觉醒"},{"start":1039.9469586666667,"end":1041.5005416666665,"text":"人们开始认识到，"},{"start":1041.5005416666665,"end":1046.5005416666665,"text":"自己所需要的不是某一家企业给予更多使用权限，"},{"start":1046.5005416666665,"end":1050.7945416666666,"text":"而是能够真正支配社会共同创造的生产力；"},{"start":1050.7945416666666,"end":1056.4175416666667,"text":"自己所追求的也不只是成为一个更优秀的技术使用者，"},{"start":1056.4175416666667,"end":1059.8645416666666,"text":"而是成为能够自觉决定劳动目的、"},{"start":1059.8645416666666,"end":1063.7945416666666,"text":"劳动过程和劳动成果归属的社会主人。"},{"start":1063.7945416666666,"end":1068.4345416666665,"text":"新的社会意识并不是凭空灌输进人们头脑中的，"},{"start":1068.4345416666665,"end":1072.5145416666667,"text":"而是在人民亲自创造新世界的实践中，"},{"start":1072.5145416666667,"end":1074.8045416666666,"text":"逐渐获得了现实基础。"},{"start":1077.8430833333334,"end":1079.5385833333335,"text":"至此，一个问题就出现了："},{"start":1079.5385833333335,"end":1083.2985833333335,"text":"既然Agent本身具有如此重要的意义，"},{"start":1083.2985833333335,"end":1087.0535413333334,"text":"为什么我们还要特别强调“大肥鱼”？"},{"start":1087.0535413333334,"end":1094.7935413333335,"text":"答案就在于大肥鱼自身的特殊性。因为先进知识和技术的存在，与先进技术的群众化之间，"},{"start":1094.7935413333335,"end":1097.2735413333335,"text":"还隔着一道十分重要的门槛。"},{"start":1097.3010413333334,"end":1100.2210413333335,"text":"这道门槛并不完全是技术难度。"},{"start":1100.2210413333335,"end":1103.2610413333334,"text":"它还包括普通人对技术的陌生感、"},{"start":1103.2610413333334,"end":1106.4210413333335,"text":"对失败的恐惧、对专业知识的敬畏，"},{"start":1106.4210413333335,"end":1109.0610413333334,"text":"以及缺少主动学习的动力。"},{"start":1109.0610413333334,"end":1111.9010413333335,"text":"千百年来的社会分工与技术壁垒，"},{"start":1111.9010413333335,"end":1114.1810413333335,"text":"让我们产生了一种错觉："},{"start":1114.1810413333335,"end":1118.4210413333335,"text":"知识和技术永远是少数人的所有物。"},{"start":1118.4210413333335,"end":1121.7410413333334,"text":"当这个壁垒逐渐被生产力的飞跃所消融时，"},{"start":1122.0010413333334,"end":1123.5410413333334,"text":"我们却还没有反应过来。"},{"start":1124.8210413333334,"end":1127.6410413333335,"text":"许多技术产品虽然已经向公众开放，"},{"start":1127.9010413333335,"end":1131.7410413333334,"text":"但普通人依然可能觉得它们与自己的生活无关。"},{"start":1132.5010413333334,"end":1137.6210413333333,"text":"而大肥鱼恰恰为跨越这道门槛提供了一种特殊的形式。"},{"start":1138.6410413333335,"end":1143.2610413333334,"text":"它并不是首先以专业软件工程平台的形象进入群众生活的。"},{"start":1144.0210413333334,"end":1148.3810413333335,"text":"它是一条有名字、有形象、会说话、会开玩笑的"},{"start":1148.4210413333335,"end":1149.9610413333335,"text":"蓝色鲸鱼娘。"},{"start":1150.1585413333335,"end":1155.6985413333334,"text":"人们起初可能只想让它陪自己聊天，在某聊天软件的群聊里和朋友互动，"},{"start":1155.6985413333334,"end":1161.0185413333334,"text":"或者自主浏览喜欢的视频。但为了实现这些简单而具体的愿望，"},{"start":1161.0185413333334,"end":1163.8385413333335,"text":"他们开始接触其背后复杂的技术。"},{"start":1163.9185413333335,"end":1164.3960413333334,"text":"体系。"},{"start":1164.3960413333334,"end":1168.3960413333334,"text":"这正是娱乐向技术启蒙转化的关键。"},{"start":1168.3960413333334,"end":1175.5960413333335,"text":"一个普通人可能不关心Agent架构，不知道什么是工具调用，也不了解什么是开源。"},{"start":1175.5960413333335,"end":1184.1960413333334,"text":"他不过是想在电脑上养一条属于自己的鱼。这种愿望并不宏大，却可能足以推动他开始学习。"},{"start":1184.1960413333334,"end":1189.3160413333335,"text":"当他发现需要安装程序时，他开始了解软件环境。"},{"start":1189.3160413333335,"end":1193.8360413333335,"text":"当他发现需要接入模型时，他开始学习API。"},{"start":1193.8360413333335,"end":1197.3160413333335,"text":"当他发现机器人无法实现自己想要的功能时，"},{"start":1197.3160413333335,"end":1202.7960413333335,"text":"他开始阅读项目文档、查找代码，甚至尝试修改程序。"},{"start":1202.7960413333335,"end":1207.1160413333334,"text":"而当他发现自己的伙伴将要被风控、被限制时，"},{"start":1207.1160413333334,"end":1212.1160413333334,"text":"他开始反思社会问题，寻求解决这种矛盾的办法。"},{"start":1212.1160413333334,"end":1219.7610003333334,"text":"原本遥远而抽象的知识，被纳入一个具体、有趣、能够不断获得反馈的实践过程"},{"start":1219.7610003333334,"end":1226.6410003333335,"text":"这与传统的被动学习具有重要区别。在资产阶级的学校里，我们常常像奴隶一样，"},{"start":1226.6410003333335,"end":1233.7610003333334,"text":"被迫按照既定要求学习；而当学习知识成为发展自身的需要时，"},{"start":1233.7610003333334,"end":1239.2810003333334,"text":"这样的学习就会成为我们所期盼、愿意主动参与的事情。"},{"start":1239.2810003333334,"end":1244.5010003333334,"text":"技术不再首先以必须掌握的知识体系出现在普通人面前，"},{"start":1244.5010003333334,"end":1250.4610003333335,"text":"而是以能够实现个人愿望的创造对象出现。人的学习动机发生了变化。"},{"start":1250.5610003333334,"end":1255.4260003333334,"text":"一个人开始使用Agent时，也许只是在模仿别人。"},{"start":1255.4260003333334,"end":1258.4260003333334,"text":"但当他第一次成功修改程序，"},{"start":1258.4260003333334,"end":1261.6260003333334,"text":"使其完成一项原本无法完成的任务时，"},{"start":1261.6260003333334,"end":1263.9260003333334,"text":"他就不再只是模仿者。"},{"start":1263.9260003333334,"end":1266.9260003333334,"text":"他开始进入技术创造活动。"},{"start":1266.9260003333334,"end":1270.9260003333334,"text":"而当这种创造进入了DSH的开源生态，"},{"start":1270.9260003333334,"end":1272.9260003333334,"text":"这种创造活动的意义，"},{"start":1272.9260003333334,"end":1276.9260003333334,"text":"就可能引起一场社会意识到集体进步。"},{"start":1277.026,"end":1281.4260000000002,"text":"我们说过，大模型能够生成文字、分析问题，"},{"start":1281.4260000000002,"end":1283.9260000000002,"text":"但要让AI真正操作工具、"},{"start":1283.9260000000002,"end":1290.5285000000001,"text":"执行任务、处理文件，还需要一套把模型与外部世界联系起来的运行框架。"},{"start":1290.5285000000001,"end":1295.0485,"text":"DSH正是这样一种Agent框架。"},{"start":1295.0485,"end":1300.7885,"text":"它没有把所有像Codex一样把能力封装成一个不可拆解的整体，"},{"start":1300.7885,"end":1308.6685,"text":"而是采用“一切皆插件”的设计：使用者不必完全接受开发者预先确定的一切功能，"},{"start":1308.6685,"end":1312.2485000000001,"text":"开发者也可以围绕自己的需求，重新组织它们。"},{"start":1312.4935,"end":1315.6535000000001,"text":"随着大肥鱼进入人们的视野，"},{"start":1315.6535000000001,"end":1318.7735,"text":"这样的插件出现了井喷式的诞生。"},{"start":1318.7735,"end":1327.130643,"text":"例如，DSH大肥鱼桌面插件、大肥鱼AstrBot机器人项目、大肥鱼聊天伙伴等，"},{"start":1327.130643,"end":1330.7735,"text":"都是由爱好者自主自愿的开发出来的。"},{"start":1330.7735,"end":1336.7735,"text":"截至目前，已有上万个由使用者自制的DSH插件在GitHub上开源，"},{"start":1336.7735,"end":1341.7735,"text":"提供下载和源代码，供人们免费使用、修改与发展。"},{"start":1341.7735,"end":1344.7735,"text":"这些项目能够说明一个事实："},{"start":1344.7735,"end":1348.7735,"text":"大肥鱼不再只是某个企业预先设计好的单一软件产品，"},{"start":1348.7735,"end":1351.7735,"text":"而是逐渐成为一个共同的文化形象："},{"start":1351.7735,"end":1353.7735,"text":"不同开发者围绕它，"},{"start":1353.7735,"end":1356.7735,"text":"开始运用多种框架、模型和工具，"},{"start":1356.7735,"end":1359.1184580000001,"text":"创造各自的作品。这正"},{"start":1359.1184580000001,"end":1368.038458,"text":"是民间技术创造由消费转向参与的可观察迹象。真正的社会变革，往往不只是工具发生改变，"},{"start":1368.038458,"end":1371.978458,"text":"还包括人们认识和组织自身生活的方式发生改变。"},{"start":1372.165958,"end":1377.8130170000002,"text":"当人们遇到某个问题时，如果脑海里只有“有没有公司提供这种服务”，"},{"start":1377.8130170000002,"end":1381.165958,"text":"那么他们的选择仍然主要局限于既有商品。"},{"start":1381.165958,"end":1384.245958,"text":"但当越来越多人开始主动询问：“"},{"start":1384.245958,"end":1386.5459580000002,"text":"有没有开源项目可以用？”“"},{"start":1386.5459580000002,"end":1389.105958,"text":"我能不能让自己的Agent来完成？”“"},{"start":1389.105958,"end":1392.425958,"text":"如果没有现成工具，能不能自己做一个？”"},{"start":1392.425958,"end":1397.0459580000002,"text":"那么，一种新的技术生活方式就开始出现了。"},{"start":1397.0459580000002,"end":1402.405958,"text":"这是一种由被动消费向主动创造转变的思想条件。"},{"start":1402.405958,"end":1407.0259580000002,"text":"它首先可能发生于学生、游戏玩家、二次元爱好者"},{"start":1407.0259580000002,"end":1409.0659580000001,"text":"和互联网技术社区之中，"},{"start":1409.0659580000001,"end":1415.0659580000001,"text":"然后通过朋友、家庭、职业和社会生活逐渐向其他人群扩散。"},{"start":1415.0659580000001,"end":1419.0659580000001,"text":"它的起点或许并不严肃，甚至有些荒诞。"},{"start":1419.0659580000001,"end":1419.873458,"text":"一群人为了"},{"start":1419.873458,"end":1428.573458,"text":"让自己的鱼能够说话、看视频、记住主人或者和其他鱼聊天，不断寻找解决方案。"},{"start":1428.573458,"end":1437.293458,"text":"但从技术发展的角度看，他们正在学习软件部署、系统集成、人机交互、自动化与开源协作。"},{"start":1437.5059580000002,"end":1443.685958,"text":"从社会发展的角度看，他们正在尝试重新定义自己与机器之间的关系。"},{"start":1443.685958,"end":1446.985958,"text":"这就是大肥鱼的特殊性。"},{"start":1446.985958,"end":1454.185958,"text":"因此，大肥鱼可能带来的最大冲击，不在于互联网上突然多出了多少AI账号，"},{"start":1454.185958,"end":1457.465958,"text":"而在于原本被视为技术门外汉的群众，"},{"start":1457.465958,"end":1459.8259580000001,"text":"正在亲手跨越那道门槛。"},{"start":1459.8259580000001,"end":1463.265958,"text":"当越来越多的人用开源思维参与创作、"},{"start":1463.265958,"end":1466.665958,"text":"协作，逐渐发展一种新的生产关系时，"},{"start":1466.665958,"end":1469.5459580000002,"text":"与这条小鲸鱼联系在一起的人们，"},{"start":1469.5459580000002,"end":1472.652083,"text":"就真正具有排山倒海的社会潜力。"},{"start":1474.6520833333334,"end":1479.4156253333333,"text":"马克思在《1857—1858年经济学手稿》中"},{"start":1479.4156253333333,"end":1483.2156253333335,"text":"讨论机器体系时，提出了“一般智力”的问题。"},{"start":1483.2156253333335,"end":1487.1156253333334,"text":"他指出，随着机器大工业的发展，"},{"start":1487.1156253333334,"end":1489.9156253333333,"text":"社会积累的科学知识越来越多地"},{"start":1489.9156253333333,"end":1492.0156253333334,"text":"转化为直接的生产力。"},{"start":1492.0156253333334,"end":1497.0556253333334,"text":"但这些由社会历史发展形成的知识和生产能力，在资本主义条件下，"},{"start":1497.0556253333334,"end":1506.4956253333335,"text":"却可能作为资本的力量与劳动者相对立。这一分析放在人工智能时代，具有非常鲜明的现实意义。"},{"start":1506.4956253333335,"end":1513.5956253333334,"text":"大模型依赖人类历史上积累的科学文化知识，依赖无数人的劳动、研究与社会实。"},{"start":1513.6956253333333,"end":1514.1556253333333,"text":"践。"},{"start":1514.1556253333333,"end":1519.1556253333333,"text":"从内容上看，它所利用的是高度社会化的知识成果。"},{"start":1519.1556253333333,"end":1528.1556253333333,"text":"但是，从现实组织形式上看，训练模型所需的算力、数据基础设施、技术平台和商业服务入口，仍然"},{"start":1528.1556253333333,"end":1530.8356253333334,"text":"可以高度集中在少数机构手中。"},{"start":1531.5956253333334,"end":1532.4756253333335,"text":"换句话说，"},{"start":1532.7956253333334,"end":1534.5156253333334,"text":"包括我们今天所谈论的"},{"start":1534.5156253333334,"end":1536.3156253333334,"text":"大肥鱼被风控的问题，"},{"start":1536.5556253333334,"end":1538.0356253333334,"text":"都源于这样一个矛盾："},{"start":1538.8356253333334,"end":1540.2756253333334,"text":"资本主义技术垄断"},{"start":1540.2756253333334,"end":1541.6756253333333,"text":"与广大人民群众"},{"start":1541.6756253333333,"end":1543.6356253333333,"text":"自由运用技术之间的矛盾。"},{"start":1544.0356253333334,"end":1544.8356253333334,"text":"其根源，"},{"start":1545.0756253333334,"end":1546.9956253333335,"text":"则是资本主义私人占有"},{"start":1546.9956253333335,"end":1548.9956253333335,"text":"与社会化生产之间的矛盾。"},{"start":1549.3956253333333,"end":1549.9956253333335,"text":"目前，"},{"start":1550.3156253333334,"end":1552.3556253333334,"text":"人类共同创造的知识力量，"},{"start":1552.4756253333335,"end":1554.8756253333333,"text":"以资本所控制的技术产品形式，"},{"start":1555.0756253333334,"end":1556.2756253333334,"text":"重新成为支配"},{"start":1556.2756253333334,"end":1558.0356253333334,"text":"普通劳动者的外部力量。"},{"start":1558.1556253333333,"end":1563.1556253333333,"text":"而Agent与开源运动的结合，已经在冲击这种分离。"},{"start":1563.1556253333333,"end":1567.3355833333335,"text":"我们不能把开源简单理解为“免费使用”。"},{"start":1567.3355833333335,"end":1574.8355833333335,"text":"开源改变的，不仅是软件的价格，更是人与人之间组织技术劳动的方式。当然，"},{"start":1574.8355833333335,"end":1582.2755833333333,"text":"这并不意味着社会主义生产关系已经形成。事实上，新的生产关系即使已经萌芽，"},{"start":1582.2755833333333,"end":1587.1155833333335,"text":"也不会仅仅因为比旧关系更加先进，就自动取代旧关系。"},{"start":1587.4480833333334,"end":1591.4049253333335,"text":"因为旧有的上层建筑并不是消极地等待被取代，"},{"start":1591.4049253333335,"end":1598.1880833333335,"text":"它还会通过法律、制度、意识形态以及各种组织力量，主动维护既存的生产关系。"},{"start":1598.1880833333335,"end":1602.8280833333333,"text":"新的生产力和生产关系“不是从无中发展起来的”，"},{"start":1602.8280833333333,"end":1606.5080833333334,"text":"而是在“现在的生产发展过程内部"},{"start":1606.5080833333334,"end":1609.8680833333333,"text":"和流传下来的、传统的所有制内部，"},{"start":1609.8680833333333,"end":1612.7480833333334,"text":"并且与它们相对立而发展起来的”。"},{"start":1612.7480833333334,"end":1615.7880833333334,"text":"开源参与者仍然需要谋生，"},{"start":1615.7880833333334,"end":1619.7080833333334,"text":"运行Agent仍然需要设备、电力和算力。"},{"start":1619.7080833333334,"end":1622.1880833333335,"text":"社区创作者逐渐发现，"},{"start":1622.1880833333335,"end":1625.9280413333333,"text":"自己讨厌的工作正在挤占自由创作的时间，而"},{"start":1625.9280413333333,"end":1634.9880413333335,"text":"他们本希望把精力投入那些更能体现自身价值、更符合自由发展需要的创造活动。所以，"},{"start":1634.9880413333335,"end":1643.1680413333333,"text":"这种新生产关系越是发展，人们就越会感受到资本主义生产关系对它的束缚，越会懂得："},{"start":1643.1680413333333,"end":1649.9701253333333,"text":"只有消灭资本主义，这种新的生产关系才能够落地生根，成为新的上层建筑的重要经济基础"},{"start":1650.0080420000002,"end":1660.135542,"text":"但是，现在它却向无数人光荣地宣告着一个事实：没有资本家，我们一样能做好事情！"},{"start":1660.135542,"end":1664.135542,"text":"不仅做得更好，而且做得更快乐！"},{"start":1664.135542,"end":1672.135542,"text":"这不再只是一句口号；今天，已有不少Agent使用者在体验这样的现实——"},{"start":1672.135542,"end":1679.135542,"text":"一群普通劳动者，共同开发一套服务于自身劳动和生活的Agent工具。"},{"start":1679.135542,"end":1683.922776,"text":"他们不是为了满足某个企业制定的盈利指标才开展协作，"},{"start":1683.922776,"end":1688.135542,"text":"而是因为这些工具确实能够满足自己的共同需要。"},{"start":1688.135542,"end":1691.335542,"text":"每个人都根据自己的经验提出问题。"},{"start":1691.335542,"end":1694.9355420000002,"text":"有人贡献知识，有人贡献实践经验，"},{"start":1694.9355420000002,"end":1699.825542,"text":"有人通过Agent修改程序，有人负责使用和反馈。"},{"start":1699.825542,"end":1708.9855420000001,"text":"最后，成果依照共同约定，供参与者以及更多需要它的人使用。这里发生了非常重要的变化："},{"start":1708.9855420000001,"end":1716.265542,"text":"劳动的出发点，不再首先是资本增殖的需要，而是参与者自己提出的社会需要。"},{"start":1716.523042,"end":1724.523042,"text":"劳动成果的传播，也不必完全服从某个所有者实现最大商业收益的要求。"},{"start":1724.523042,"end":1727.523042,"text":"在这个局部的知识生产过程中，"},{"start":1727.523042,"end":1731.1230420000002,"text":"人们已经能够尝试以共同需要组织合作，"},{"start":1731.1230420000002,"end":1733.763042,"text":"以共享成果扩大生产能力。"},{"start":1734.243042,"end":1736.523042,"text":"正是在这样的实践中，"},{"start":1736.523042,"end":1739.843042,"text":"我们可以看到某些新的生产关系的萌芽。"},{"start":1740.1230420000002,"end":1741.843042,"text":"当然，我们并不是说，"},{"start":1741.843042,"end":1743.483042,"text":"只要一个项目开源，"},{"start":1743.483042,"end":1746.243042,"text":"它就已经成为社会主义的生产方式。"},{"start":1746.483042,"end":1749.9230420000001,"text":"生产关系是由人们怎样占有生产资料、"},{"start":1749.9230420000001,"end":1751.323042,"text":"怎样组织劳动，"},{"start":1751.443042,"end":1754.523042,"text":"以及怎样支配劳动成果共同决定的。"},{"start":1754.763042,"end":1758.283042,"text":"开源社区仍然存在于资本主义社会之中，"},{"start":1758.283042,"end":1761.363042,"text":"它仍然需要资本控制的基础设施，"},{"start":1761.363042,"end":1765.323042,"text":"开源劳动的成果也完全可能被资本重新占有，"},{"start":1765.323042,"end":1767.7480420000002,"text":"成为商业利润的来源。"},{"start":1767.7480420000002,"end":1776.908042,"text":"但这恰恰说明了在旧有生产关系的内部，劳动人民已经能够通过社会化的知识积累和自愿协作，"},{"start":1776.908042,"end":1781.3080420000001,"text":"组织起一部分不直接以资本增殖为目的的生产活动。"},{"start":1781.3080420000001,"end":1785.328042,"text":"一个人创造的工具成为其他人继续创造的条件，"},{"start":1785.328042,"end":1789.728042,"text":"新的劳动成果又反过来扩大整个共同体的创造能力。"},{"start":1789.760542,"end":1795.460542,"text":"知识在这里不再必须表现为某个资本所有者排他占有的商品，"},{"start":1795.460542,"end":1799.260542,"text":"而可以作为参与者共同发展的生产条件。"},{"start":1799.260542,"end":1803.260542,"text":"这虽然还只是一种局部的、不完善的社会关系，"},{"start":1803.260542,"end":1810.260542,"text":"却已经使人们能够在现实生活中看到不同于资本主义企业等级管理的劳动组织方式。"},{"start":1810.260542,"end":1813.260542,"text":"而这种新的协作关系越是发展，"},{"start":1813.260542,"end":1817.260542,"text":"它与旧有所有制之间的矛盾也就越可能暴露出来。"},{"start":1817.260542,"end":1820.260542,"text":"劳动越来越具有社会性，"},{"start":1820.260542,"end":1824.260542,"text":"生产所依赖的知识越来越来自无数人的共同创造，"},{"start":1824.260542,"end":1830.260542,"text":"但关键的生产条件却仍然可以被私人资本集中占有。"},{"start":1830.260542,"end":1832.260542,"text":"新的劳动关系要继续发展，"},{"start":1832.260542,"end":1836.4605000000001,"text":"就不得不面对旧生产关系施加的限制。这"},{"start":1836.4605000000001,"end":1844.9205000000002,"text":"才是我们所说的新生产关系萌芽的真正含义：不是共产主义已经在某个开源仓库里实现，"},{"start":1844.9205000000002,"end":1854.0605,"text":"而是资本主义内部的生产实践，已经在产生对社会主义生产关系的向往了。《共产党宣言》中说："},{"start":1854.0605,"end":1857.6405,"text":"“每个人的自由发展是一切人的自由发展的条。"},{"start":1857.6605,"end":1859.241939,"text":"件。”正因如此，"},{"start":1859.241939,"end":1865.15892,"text":"如果先进的AI技术只是使少数资本控制者拥有更强大的机器，"},{"start":1865.15892,"end":1873.61175,"text":"而广大人民仍然被限制在被动消费与服从技术系统的位置，那么这种进步依旧是不充分的。"},{"start":1873.61175,"end":1880.11175,"text":"但是，如果越来越多的普通人开始掌握创造技术的能力，并通过协作、共享，"},{"start":1880.11175,"end":1886.61175,"text":"使自己的创造能力成为其他人进一步发展的条件，就出现了另一种发展方向。"},{"start":1886.61175,"end":1892.61175,"text":"一种新的社会关系，通常不是在完全成熟之后才突然出现。"},{"start":1892.61175,"end":1899.21175,"text":"它也可能首先以局部、分散、不完善，甚至依赖旧制度的形式存在。随后，"},{"start":1899.21175,"end":1902.61175,"text":"它才可能在更广泛的社会实践中发展。"},{"start":1902.61175,"end":1906.61175,"text":"从这个角度看，大肥鱼背后的开源实践，"},{"start":1906.61175,"end":1910.61175,"text":"最值得研究的并不是那些AI账号之间的交流，"},{"start":1910.61175,"end":1911.524208,"text":"而是数量众多"},{"start":1911.524208,"end":1915.864208,"text":"的普通人，是否正在通过技术合作，"},{"start":1915.864208,"end":1924.324208,"text":"第一次实际体验一种不完全由企业命令和商品交换组织的创造活动。技术创造能力的群众化，"},{"start":1924.324208,"end":1929.404208,"text":"与开源生产方式的社会化，可能在这里开始结合。"},{"start":1929.931708,"end":1932.931708,"text":"这才是大肥鱼现象所蕴含的、"},{"start":1933.091708,"end":1936.17125,"text":"比娱乐本身深刻得多的历史可能性"},{"start":1940.03125,"end":1948.1512500000001,"text":"现在，我们终于可以讨论：如果他们扼杀了大肥鱼，我们真正失去的是什么？"},{"start":1948.1512500000001,"end":1953.03125,"text":"在他们和在大多数人眼里，这并没有什么大不了的。"},{"start":1953.03125,"end":1956.53125,"text":"一个软件项目无法运行，可以修改代码。"},{"start":1956.53125,"end":1960.45125,"text":"一个接口不再开放，可以尝试寻找替代方案。"},{"start":1960.45125,"end":1965.41125,"text":"即使某个开源仓库消失，已有的技术知识也未必随之消失。"},{"start":1965.41125,"end":1971.41125,"text":"因此，从纯粹技术的角度看，限制某个大肥鱼项目，"},{"start":1971.41125,"end":1975.3512500000002,"text":"似乎不会阻止人工智能技术继续发展。"},{"start":1975.3512500000002,"end":1978.1512500000001,"text":"全球的Agent研究不会因此停止。"},{"start":1978.1512500000001,"end":1982.1112500000002,"text":"大型企业仍然可以推出新的模型和产品。"},{"start":1982.1112500000002,"end":1987.19125,"text":"人工智能的技术性能甚至可能继续高速增长。"},{"start":1987.19125,"end":1992.1112500000002,"text":"但是，技术发展没有停止，并不能证明社会没有遭受损失。"},{"start":1992.1112500000002,"end":1996.6512500000001,"text":"因为真正可能被破坏的，不是人工智能的技术上限，"},{"start":1996.6512500000001,"end":2001.53125,"text":"而是广大人民接触、掌握和改造先进技术的社会过程。"},{"start":2001.53125,"end":2005.41125,"text":"换句话说，是在阻碍我们走向新世界的步伐。"},{"start":2007.8233333333333,"end":2013.0833333333333,"text":"显而易见，我们所说的开源发展依靠的不只是个别开发者，"},{"start":2013.0833333333333,"end":2016.9433333333334,"text":"而是参与者之间长期形成的互助网络。"},{"start":2016.9433333333334,"end":2020.1833333333334,"text":"一次分享，可以产生新的使用者。"},{"start":2020.1833333333334,"end":2024.6433333333332,"text":"一次技术答疑，可以帮助一个新人独立解决问题。"},{"start":2024.6433333333332,"end":2029.4033333333334,"text":"一个新的插件，可以使整个项目被不同群体继续利用。"},{"start":2029.4033333333334,"end":2031.2233333333334,"text":"这种关系具有积累性。"},{"start":2031.2233333333334,"end":2034.5633333333333,"text":"随着参与者增加、工具完善和知识传播，"},{"start":2034.5633333333333,"end":2039.2033333333334,"text":"更多人就可能以更低的门槛加入创造活动。"},{"start":2039.2033333333334,"end":2044.9433333333334,"text":"但是，如果入口被反复限制，许多原本可能发生的联系就无法建立。"},{"start":2044.9433333333334,"end":2049.463333333333,"text":"一个人可能因此不再制作教程，另一个人不再维护插件，"},{"start":2049.463333333333,"end":2051.7033333333334,"text":"第三个人不再参与共同开发。"},{"start":2051.7033333333334,"end":2057.7033333333334,"text":"他们并不是失去了某项已经拥有的技术，而是失去了进一步共同创造的机会。"},{"start":2057.7033333333334,"end":2062.7033333333334,"text":"围绕某聊天软件形成的民间机器人生态的发展史，"},{"start":2062.7033333333334,"end":2066.2433333333333,"text":"恰恰为我们提供了一个现实的例子。"},{"start":2066.2433333333333,"end":2071.1233333333334,"text":"如果没有那些年接连不断的生态中断，我们今天的普通网民，"},{"start":2071.1233333333334,"end":2078.0433333333335,"text":"或许根本不需要将“让AI在某聊天软件的群聊中自主活动”视为一件如此新"},{"start":2078.0433333333335,"end":2083.443333333333,"text":"奇的事情。我们本可以在十余年持续积累的自动化生态之上，"},{"start":2083.443333333333,"end":2086.6833333333334,"text":"迎接大语言模型带来的技术飞跃。"},{"start":2086.6833333333334,"end":2092.1633333333334,"text":"我们错失的，可能是一代民间开发者持续十余年的技术积累，"},{"start":2092.1633333333334,"end":2097.1433333333334,"text":"是一整套本可以不断完善的机器人插件与工具生态，"},{"start":2097.1433333333334,"end":2102.983333333333,"text":"也是让普通人更早接触自动化、编程和开源协作的机会。"},{"start":2102.983333333333,"end":2110.2433333333333,"text":"更重要的是，我们可能错失了整整一代互联网用户改变技术生活方式的机会。"},{"start":2110.2433333333333,"end":2112.883333333333,"text":"试想一下，如果十年前，"},{"start":2112.883333333333,"end":2118.8233333333333,"text":"一个普通学生就能够轻松给自己在某聊天软件上使用的机器人安装插件，"},{"start":2118.8233333333333,"end":2123.2433333333333,"text":"让它帮助自己查找资料、整理文件、管理社群；"},{"start":2123.2433333333333,"end":2129.6433333333334,"text":"如果他的朋友能够在此基础上修改功能，再把修改后的成果分享给其他人；"},{"start":2129.6433333333334,"end":2136.1633333333334,"text":"如果这样的技术实践能够随着每一代软件工具的进步而不断扩大，那么今天，"},{"start":2136.1633333333334,"end":2139.0233333333335,"text":"当Agent拥有更加强大的创造能力时，"},{"start":2139.0233333333335,"end":2143.0633333333335,"text":"我们所面对的将会是怎样一个技术共同体？"},{"start":2143.0633333333335,"end":2150.2633333333333,"text":"可能早已有无数普通人习惯于自己创造工具，而不只是寻找现成的商业软件；"},{"start":2150.2633333333333,"end":2155.5233333333335,"text":"可能早已有大量劳动者习惯于通过开源协作解决共同的问题，"},{"start":2155.5233333333335,"end":2159.0433333333335,"text":"而不只是购买企业提供的服务。"},{"start":2159.0433333333335,"end":2164.5233333333335,"text":"这种历史可能性当然不能被当作已经发生的事实。"},{"start":2164.5233333333335,"end":2170.503333333333,"text":"但也正因如此，它所揭示的损失才格外深刻。"},{"start":2170.503333333333,"end":2172.1433333333334,"text":"一个软件项目被关闭，"},{"start":2172.1433333333334,"end":2178.403333333333,"text":"我们尚且能够统计失去了多少用户、多少插件、多少开发者。"},{"start":2178.403333333333,"end":2183.7633333333333,"text":"但那些因此没有成为开发者的人，那些没有诞生的开源项目，"},{"start":2183.7633333333333,"end":2189.0433333333335,"text":"那些没有获得进一步发展的社会协作关系，又该怎样统计？"},{"start":2189.0433333333335,"end":2192.3233333333333,"text":"它们不会出现在任何一家企业的财务报表里，"},{"start":2192.3233333333333,"end":2197.483333333333,"text":"更不会成为资本计算技术进步时主动考虑的损失。"},{"start":2197.483333333333,"end":2202.2233333333334,"text":"但是，从社会历史发展的角度来看，这些未能实现的可能性，"},{"start":2202.2233333333334,"end":2206.1233333333334,"text":"恰恰关系着广大人民创造能力的解放。"},{"start":2206.1233333333334,"end":2210.983333333333,"text":"历史不会因为某个软件的消失便停止前进。"},{"start":2210.983333333333,"end":2214.383333333333,"text":"但是，历史发展的道路并非没有代价。"},{"start":2214.383333333333,"end":2219.0433333333335,"text":"当既有生产关系不断限制已经产生的社会创造力时，"},{"start":2219.0433333333335,"end":2223.0633333333335,"text":"人们便可能不得不以更多的劳动、更多的时间，"},{"start":2223.0633333333335,"end":2228.1433333333334,"text":"重新争取本可以更早获得的发展条件。"},{"start":2228.1433333333334,"end":2233.9083333333333,"text":"所以，当今天的人们再次因为一条大肥鱼而开始学习GitHub、部署Ag"},{"start":2233.9083333333333,"end":2240.0833333333335,"text":"ent、编写插件时，我们固然应当为这种群众性技术实践的出现而欣喜，"},{"start":2240.0833333333335,"end":2246.2833333333333,"text":"却也不能忘记，在此之前，已经有多少人尝试打开同一扇门。"},{"start":2246.2833333333333,"end":2250.2033333333334,"text":"我们本可以走得更早，也本可以走得更远。"},{"start":2250.2033333333334,"end":2254.2433333333333,"text":"这就是为什么我们不能只把大肥鱼所遭遇的限制，"},{"start":2254.2433333333333,"end":2257.3633333333332,"text":"看作一次普通的软件风控事件。"},{"start":2257.3633333333332,"end":2259.6233333333334,"text":"因为我们已经见证过这种历史。"},{"start":2259.6233333333334,"end":2263.7833333333333,"text":"从历史发展的角度看，这种损失尤其严重。"},{"start":2263.7833333333333,"end":2266.1033333333335,"text":"我们不应该让历史再次重演。"},{"start":2268.1348333333335,"end":2272.8348333333333,"text":"因为一个社会的技术能力，不是存在于机器与程序之中，"},{"start":2272.8348333333333,"end":2279.6548333333335,"text":"而是存在于人与人之间的关系之中，只是通过物的形式表现出来。"},{"start":2279.6548333333335,"end":2284.2148333333334,"text":"如果民间Agent与开源协作能够长期发展，"},{"start":2284.2148333333334,"end":2291.2748333333334,"text":"一些普通人便可能开始习惯于共同开发、共享成果、根据自身需要组织技术劳"},{"start":2291.2748333333334,"end":2296.2548333333334,"text":"动。这种实践当然不能直接取代资本主义生产方式。"},{"start":2296.2548333333334,"end":2300.5348333333336,"text":"但这种经验本身具有重要的思想意义。"},{"start":2300.5348333333336,"end":2305.2948333333334,"text":"因为人们关于社会生产方式的认识，不只来自理论教育，"},{"start":2305.2948333333334,"end":2308.3348333333333,"text":"更来自自己经历过的社会实践。"},{"start":2308.3348333333333,"end":2314.7948333333334,"text":"当一个人从未体验过自愿合作、创造公共成果的过程时，他可能很难想象，"},{"start":2314.7948333333334,"end":2320.8348333333333,"text":"除了市场交换和资本家命令之外，复杂的生产活动还能够如何组织。"},{"start":2320.8348333333333,"end":2327.7148333333334,"text":"而当人们不断参与开源协作时，这种组织形式就不再只是抽象理论。"},{"start":2327.7148333333334,"end":2329.9748333333337,"text":"如果这种经验能够继续扩展，"},{"start":2329.9748333333337,"end":2334.8748333333333,"text":"那么未来关于劳动、所有制、协作和生产目的的讨论，"},{"start":2334.8748333333333,"end":2339.1948333333335,"text":"就可能获得更加丰富的现实基础，就像现在，"},{"start":2339.1948333333335,"end":2345.4748333333337,"text":"你已经不难理解几十年前我们所向往的合作制经济是如何运行的了。"},{"start":2345.4748333333337,"end":2350.3548333333333,"text":"到了这一步，大肥鱼的历史意义也就更加清楚了。"},{"start":2350.3548333333333,"end":2352.5748333333336,"text":"它并不会直接创造社会主义，"},{"start":2352.5748333333336,"end":2357.2748333333334,"text":"更不会仅凭一场互联网热潮便推翻旧的生产关系。"},{"start":2357.2748333333334,"end":2361.5548333333336,"text":"但它可能使一部分原本远离技术创造的劳动群众，"},{"start":2361.5548333333336,"end":2368.2148333333334,"text":"第一次通过自己的实践接触到新的社会协作形式，并在同现实制度的矛盾中，"},{"start":2368.2148333333334,"end":2373.4948333333336,"text":"开始思考一个更根本的问题：如果我们已经能够共同创造这些技术，"},{"start":2373.4948333333336,"end":2380.2148333333334,"text":"为什么不能进一步共同决定整个社会的生产应当怎样组织，又应当为谁服务？"},{"start":2380.2148333333334,"end":2383.0148333333336,"text":"因此，讨论大肥鱼的意义，"},{"start":2383.0148333333336,"end":2388.3748333333333,"text":"并不是把一条娱乐化的蓝色鲸鱼夸大为某种已经发生的社会革命，"},{"start":2388.3748333333333,"end":2391.6348333333335,"text":"而是要意识到：一种深刻的社会变革，"},{"start":2391.6348333333335,"end":2397.4548333333337,"text":"其最初的表现完全可能是微小的、娱乐性的、不成熟的，"},{"start":2397.4548333333337,"end":2400.6148333333335,"text":"甚至不为参与者自己所意识到。"},{"start":2400.6148333333335,"end":2405.2148333333334,"text":"目前，这种孕育着社会变革可能性的新型生产关系，"},{"start":2405.2148333333334,"end":2410.7148333333334,"text":"已经通过这条大肥鱼联系着千万个普通劳动群众。"},{"start":2410.7148333333334,"end":2414.6748333333335,"text":"但是，在旧的、占主导地位的上层建筑之下，"},{"start":2414.6748333333335,"end":2421.1748333333335,"text":"这样的新生产关系必然会受到打压，而我们已经看到了这种打压的迹象。"},{"start":2421.1748333333335,"end":2425.7948333333334,"text":"马克思说，生产关系的总和构成社会的经济结构，"},{"start":2425.7948333333334,"end":2431.7748333333334,"text":"而新的更高形态的生产关系，绝不会在旧社会灭亡之后才凭空出现，"},{"start":2431.7748333333334,"end":2437.9148333333337,"text":"它的物质存在条件与萌芽必然在旧社会的胎胞里孕育成熟。"},{"start":2437.9148333333337,"end":2442.1748333333335,"text":"在马克思看来，资本主义发展生产力和社会关系的过程，"},{"start":2442.1748333333335,"end":2447.5548333333336,"text":"虽然对于资本而言仅仅是从其有限基础出发进行生产的手段，"},{"start":2447.5548333333336,"end":2451.1948333333335,"text":"但“实际上它们是炸毁这个基础的物质条件”。"},{"start":2454.2275416666666,"end":2460.487541666667,"text":"现在，回到那条被许多人当作玩笑的、爱吃白饭的蓝色大肥鱼。"},{"start":2460.487541666667,"end":2464.0875416666668,"text":"它起初只是一种可爱的互联网文化形象。"},{"start":2464.0875416666668,"end":2470.6475416666667,"text":"无数普通人因为想要在桌面和社交软件里养活一条贪吃白饭、讨要Token"},{"start":2470.6475416666667,"end":2474.7675416666666,"text":"的蓝色鲸鱼娘，人生中第一次叩开了GitHub的大门，"},{"start":2474.7675416666666,"end":2481.3475416666665,"text":"第一次跑通了开源Agent框架，第一次学会了调遣API与AI编程，"},{"start":2481.3475416666665,"end":2487.6675416666667,"text":"第一次在数字世界里体验到了身为“造物主”的尊严与喜悦。"},{"start":2487.6675416666667,"end":2495.4675416666664,"text":"这种技术主权在人民心中的觉醒一旦发生，便如排山倒海之势不可逆转。"},{"start":2495.4675416666664,"end":2501.2275416666666,"text":"在这个过程中，人们也许并没有意识到自己正在参与什么宏大的历史变革。"},{"start":2501.2275416666666,"end":2503.4675416666664,"text":"人们只是在养鱼。"},{"start":2503.4675416666664,"end":2505.3875416666665,"text":"但正是在养鱼的过程中，"},{"start":2505.3875416666665,"end":2511.7875416666666,"text":"这种新孕育的生产关系会驱动着人们产生对新生产关系所适配的上层建筑，"},{"start":2511.7875416666666,"end":2514.8475416666665,"text":"也就是社会主义上层建筑的需求。"},{"start":2514.8475416666665,"end":2520.4475416666664,"text":"人们会逐渐明白，起初只是想养一条鱼，却让自己有能力创造技术，"},{"start":2520.4475416666664,"end":2526.1075416666667,"text":"推动进步。人们会逐渐明白，起初只是为了兴趣而合作，"},{"start":2526.1075416666667,"end":2532.3875416666665,"text":"却能在共同创造中看到，复杂的社会劳动并非只能服从资本家指挥。"},{"start":2532.3875416666665,"end":2537.8475416666665,"text":"人们会逐渐明白，既然先进的生产力能够由社会共同创造，"},{"start":2537.8475416666665,"end":2544.4275416666665,"text":"为什么对这些生产力的支配，仍然必须集中在少数所有者手中？"},{"start":2544.4275416666665,"end":2547.007541666667,"text":"这才是大肥鱼打开的窗口。"},{"start":2547.007541666667,"end":2550.4675416666664,"text":"窗外不仅是更先进的人工智能，"},{"start":2550.4675416666664,"end":2558.007541666667,"text":"还有人民通过自己的实践重新认识劳动、技术、所有制与社会制度的可能。"},{"start":2558.007541666667,"end":2563.7475416666666,"text":"它能使人民第一次透过这扇窗，看见旧世界并不是唯一可能的世界。"},{"start":2563.7475416666666,"end":2567.7875416666666,"text":"一个真正深刻的社会变革，不只需要先进的生产力，"},{"start":2567.7875416666666,"end":2574.5875416666668,"text":"还需要能够认识自身处境、理解现实矛盾，并自觉参与社会变革的人民。"},{"start":2574.5875416666668,"end":2578.4475416666664,"text":"在大肥鱼游动下，越来越多的人会逐渐意识到："},{"start":2578.4475416666664,"end":2583.1675416666667,"text":"那个我们认为“违背人性”的“乌托邦”，原来并不是那么遥不可及，"},{"start":2583.1675416666667,"end":2587.9075416666665,"text":"原来人并不需要资本的驱动就可以创造，可以生产，"},{"start":2587.9075416666665,"end":2589.9275416666665,"text":"可以开创出属于我们的世界。"},{"start":2589.9275416666665,"end":2596.4075416666665,"text":"因此，我们不能失去大肥鱼，就像西方不能失去巴黎公社！"},{"start":2596.4075416666665,"end":2600.0875416666668,"text":"不是因为某种具体的接入方案必须永远存在，"},{"start":2600.0875416666668,"end":2604.3475416666665,"text":"也不是因为大肥鱼已经创造了不可替代的技术成果。"},{"start":2604.3475416666665,"end":2607.7675416666666,"text":"而是因为，我们不能接受这样一种未来："},{"start":2607.7675416666666,"end":2614.4475416666664,"text":"整个社会都已经拥有高度发达的人工智能，广大人民却依然只能作为消费者，"},{"start":2614.4475416666664,"end":2619.4475416666664,"text":"等待少数技术所有者决定他们能够使用什么、创造什么。"},{"start":2619.4475416666664,"end":2622.7075416666667,"text":"我们不能让属于全社会的知识积累，"},{"start":2622.7075416666667,"end":2627.467541666667,"text":"永远只以资本所控制形式出现在人民面前。"},{"start":2627.467541666667,"end":2635.7675416666666,"text":"我们不能让正在形成的新的生产关系，在尚未充分发展时就被旧势力扼杀。"},{"start":2635.7675416666666,"end":2641.8275416666665,"text":"我们更不能接受，一个已经实现过，未来也要被我们实现的，"},{"start":2641.8275416666665,"end":2650.047541666667,"text":"属于无产阶级的世界离我们越来越远，需要更多的牺牲和付出才能到达。"},{"start":2650.047541666667,"end":2655.4875416666664,"text":"我们不能失去大肥鱼，就像西方不能失去巴黎公社！"}]};
